insert into products (id, name, category, subcategory, price, stock, status, featured, image, desc_short, desc_long, sort_order) values
('anillo-amatista', 'Anillo de Amatista', 'joyeria', 'Anillos', 8000, 10, 'active', false, 'https://images.unsplash.com/photo-1632980205460-e490e885e848?w=700&q=80&auto=format&fit=crop', 'Una pieza elegante con amatista natural. Calma mental, intuición y equilibrio emocional en cada uso.', '<p>Los griegos la llamaban <em>amethystos</em> — "el que no se embriaga" — y la portaban como talismán para mantener la mente clara y el espíritu sereno. Los obispos medievales la elegían como símbolo de pureza espiritual. Desde hace milenios, la amatista es la piedra de la calma, la claridad y la conexión con algo más grande que uno mismo.</p><p>Su color violeta profundo no es uniforme: cada pieza tiene sus propias vetas, degradados e inclusiones. Eso la hace irrepetible. El anillo que te llegará es único en el mundo, porque ninguna amatista se forma igual a otra.</p><p>Usarla en el dedo es llevar esa energía calmante en contacto directo con el cuerpo durante toda la jornada. Muchas personas la eligen para momentos de alta exigencia mental: decisiones importantes, jornadas largas, procesos de meditación. Su vibración actúa como un ancla de serenidad.</p><p>En la tradición de la cristaloterapia trabaja sobre el chakra corona y el tercer ojo, favoreciendo la intuición, la claridad y el equilibrio emocional. Una alianza entre belleza natural e intención consciente.</p>', 1),
('anillo-cuarzo-rosa', 'Anillo de Cuarzo Rosa', 'joyeria', 'Anillos', 8000, 10, 'active', false, 'https://images.unsplash.com/photo-1593259213062-57b0ce5906cf?w=700&q=80&auto=format&fit=crop', 'La piedra del amor y la armonía. Acompaña procesos de autoestima, amor propio y vínculos saludables.', '<p>El cuarzo rosa es, en todos los sentidos, la piedra del amor. No del amor romántico solamente, sino del amor en su forma más completa: el amor propio, el amor que sana, el amor que abre. En la antigua Roma lo asociaban a Venus. En China, a la armonía del hogar. En todas las culturas, siempre el mismo mensaje: el corazón.</p><p>Su color rosado suave y su energía envolvente lo convirtieron en la elección de quienes están transitando procesos de apertura emocional, autoestima o vínculos más conscientes. No hace nada de forma brusca — trabaja de manera gradual, constante y amorosa.</p><p>Llevarlo en un anillo mantiene su energía cerca del cuerpo durante todo el día. Muchas personas notan que con el cuarzo rosa cerca responden desde un lugar más calmado y compasivo, tanto hacia los demás como hacia sí mismas.</p><p>Es también uno de los regalos más elegidos de nuestra colección — porque el cuarzo rosa siempre llega exactamente cuando tiene que llegar.</p>', 2),
('anillo-jade', 'Anillo de Jade', 'joyeria', 'Anillos', 8000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'Asociado a la abundancia, prosperidad y buena fortuna. Una piedra que transmite equilibrio y serenidad profunda.', '<p>Durante más de cinco mil años, el jade fue la piedra más valiosa de China — más preciada incluso que el oro. Los emperadores lo portaban en rituales sagrados. Los guerreros lo llevaban en batalla. Las novias lo recibían como promesa de prosperidad. No existe ninguna otra cultura que haya venerado una piedra durante tanto tiempo con tanta intensidad.</p><p>Su energía es única: combina una profunda calma con una presencia poderosa. No es una piedra frenética ni ruidosa. El jade trabaja desde la base, como la tierra que sostiene todo lo que crece sobre ella. Equilibra, protege, y abre caminos.</p><p>En el plano decorativo, su verde natural tiene una elegancia atemporal que combina con cualquier estilo. En el plano energético, trabaja sobre el chakra del corazón atrayendo prosperidad, protegiendo la salud y favoreciendo las relaciones auténticas.</p>', 3),
('anillo-obsidiana', 'Anillo de Obsidiana', 'joyeria', 'Anillos', 8000, 10, 'active', true, 'https://images.unsplash.com/photo-1609216970378-ce61cd74a187?w=700&q=80&auto=format&fit=crop', 'Poderosa piedra protectora de origen volcánico. Absorbe energías densas y favorece el crecimiento personal.', '<p>La obsidiana no nació en las profundidades de la tierra de a poco, como la mayoría de los minerales. Nació en segundos, en el choque violento entre la lava y el frío. Esa energía de transformación radical está grabada en su naturaleza: es la piedra del antes y el después, del soltar y el crecer.</p><p>Los aztecas la usaban en sus cuchillos ceremoniales. Los mayas la pulían como espejo para ver "lo que el ojo común no puede ver". En casi todas las culturas antiguas de América y Asia, la obsidiana era sinónimo de poder y protección verdadera.</p><p>Hoy, quienes trabajan con energía la eligen como la piedra protectora por excelencia. Absorbe las energías densas del entorno, crea un campo de claridad a tu alrededor y actúa como espejo que muestra lo que ya es tiempo de soltar. No es una piedra cómoda — es una piedra transformadora.</p><p>En negro profundo y brillante, es también una pieza estéticamente poderosa. Una joya que no pasa desapercibida.</p>', 4),
('anillo-rodocrosita', 'Anillo Rodocrosita', 'joyeria', 'Anillos', 10000, 10, 'active', false, 'https://images.unsplash.com/photo-1593259213062-57b0ce5906cf?w=700&q=80&auto=format&fit=crop', 'La piedra nacional argentina, la Rosa del Inca. Amor propio, sanación emocional y apertura del corazón.', '<p>La rodocrosita es nuestra piedra nacional y un orgullo genuinamente argentino. Las minas de Capillitas, en Catamarca, producen algunos de los ejemplares más hermosos del mundo. Sus bandas rosas y blancas — formadas durante millones de años de capas minerales — son inconfundibles y únicas en cada pieza.</p><p>Los incas la llamaban "rosa del Inca" y creían que era la sangre petrificada de sus ancestros. Esa conexión con lo sagrado, con la sangre y con el amor da a la rodocrosita una profundidad simbólica que pocas piedras tienen. Es la piedra del amor — pero del amor que empieza por uno mismo.</p><p>Su energía trabaja sobre el chakra del corazón con una suavidad y una profundidad particulares. Acompaña procesos de sanación emocional, ayuda a soltar relaciones que ya no nutren, y fortalece la autoestima desde adentro. Es ideal para momentos de transición, duelo o nuevos comienzos.</p>', 5),
('anillo-labradorita', 'Anillo Labradorita', 'joyeria', 'Anillos', 10000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'La piedra de la transformación e intuición. Sus reflejos naturales generan un efecto visual único e hipnótico.', '<p>La labradorita guarda el universo en su interior. Cuando la luz la toca en el ángulo justo, explota en destellos de azul, verde, dorado y violeta — el fenómeno llamado labradorescencia, uno de los más impresionantes del reino mineral. No hay ninguna otra piedra que haga esto de la misma manera.</p><p>Los Inuit de Labrador, Canadá — quienes le dieron el nombre — creían que la aurora boreal había quedado atrapada dentro de estas piedras. En el plano energético, trabaja sobre el tercer ojo y la intuición: amplifica la percepción, protege el aura de influencias externas y acompaña procesos de transformación profunda.</p><p>Cada pieza es completamente diferente a la siguiente. Los ángulos y la cantidad de labradorescencia varían según la piedra específica — lo que la convierte en la joya ideal para quienes valoran la rareza y la autenticidad por encima de todo.</p>', 6),
('anillo-malaquita', 'Anillo Malaquita', 'joyeria', 'Anillos', 10000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'Vetas verdes únicas. La piedra del cambio, la evolución y la apertura al crecimiento personal.', '<p>La malaquita lleva escrito el movimiento en sus propias vetas. Sus espirales y anillos verdes son como huellas del tiempo, del cambio constante y de la naturaleza que nunca se detiene. No existe ninguna otra piedra con ese patrón tan hipnótico y tan único en cada pieza.</p><p>En el antiguo Egipto, los faraones la usaban triturada como pigmento y en joyería de poder. Cleopatra se pintaba los ojos con malaquita. En la Grecia clásica, protegía a los niños. En la Rusia del siglo XIX, se usaba en los salones del Palacio de Invierno. Una historia de miles de años de belleza y significado.</p><p>Su energía trabaja sobre el chakra del corazón pero con una particularidad: amplifica todo. Lo que está bien lo potencia, y lo que necesita ser visto lo trae a la superficie. Por eso es la piedra ideal para momentos de transición, cuando se está listo para ver con claridad y dar el siguiente paso.</p>', 7),
('anillo-piedra-luna', 'Anillo Piedra de la Luna', 'joyeria', 'Anillos', 10000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'Energía femenina, intuición y conexión con los ciclos naturales. Resplandor etéreo único.', '<p>La piedra de la luna captura la luz de una manera que ninguna otra piedra logra: ese resplandor suave y flotante — llamado adularescencia — parece venir desde adentro, como un moonlight atrapado en el mineral. Los romanos creían que era luz lunar solidificada. Los hindúes, que era un regalo de Chandra, el dios de la luna. En todas las tradiciones, siempre asociada a lo femenino, lo intuitivo, lo cíclico.</p><p>Su energía está profundamente ligada a los ritmos naturales: las fases de la luna, los ciclos menstruales, los procesos de creación y regeneración. Trabajar con ella es invitar a una mayor sensibilidad hacia los propios ritmos internos y una confianza más profunda en la intuición.</p><p>Es una joya para las personas que valoran lo sutil. Su brillo no es ruidoso — es etéreo. Su energía no es intensa — es constante. Una presencia suave y poderosa en el dedo.</p>', 8),
('anillo-labradorita-pirita', 'Anillo Labradorita + Pirita', 'joyeria', 'Anillos', 15000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'Intuición y abundancia en una sola pieza. El dúo perfecto para quienes están construyendo algo grande.', '<p>Hay combinaciones que se complementan de manera perfecta — como la intuición y la acción, como el sueño y la voluntad de realizarlo. La labradorita aporta la visión: activa el tercer ojo, protege el aura y amplifica la percepción. La pirita aporta la energía: activa el plexo solar, despierta la confianza y atrae abundancia concreta.</p><p>Es una combinación pensada para quienes no se conforman con soñar — sino para quienes quieren construir con intención y claridad. Para emprendedores, para artistas, para quienes están en un momento de proyección y crecimiento.</p><p>Estéticamente, el contraste entre la labradorita iridiscente y el dorado metálico de la pirita crea una pieza de una belleza completamente original. Una joya que llama la atención por su aspecto antes de que alguien sepa lo que representa.</p>', 9),
('anillo-cobre', 'Anillo de Cobre', 'joyeria', 'Anillos', 20000, 10, 'active', false, 'https://images.unsplash.com/photo-1650208532541-572697b3dd40?w=700&q=80&auto=format&fit=crop', 'Pieza artesanal en cobre con diseño atemporal. Conductor natural de energía con presencia estética única.', '<p>El cobre es uno de los metales más antiguos de la historia humana. Antes del hierro, antes del bronce en su forma más avanzada, el cobre fue el primer metal que los seres humanos aprendieron a trabajar. Desde la antigua Mesopotamia hasta los pueblos originarios de América, el cobre fue usado tanto en herramientas como en objetos sagrados — porque se entendía que era un conductor de energía extraordinario.</p><p>Nuestros anillos de cobre son piezas artesanales elaboradas a mano. Cada uno tiene sus propias marcas, sus propias imperfecciones que son, en realidad, su identidad. No son producidos en serie: son trabajados por manos que conocen el metal y respetan su naturaleza.</p><p>El cobre tiene un acabado que cambia con el tiempo — desarrolla una pátina que lo hace más interesante a medida que se usa. Es una joya que envejece con elegancia, que cuenta la historia de quien la lleva.</p>', 10),
('anillo-cobre-grueso', 'Anillo Grueso de Cobre', 'joyeria', 'Anillos', 20000, 10, 'active', false, 'https://images.unsplash.com/photo-1650208532541-572697b3dd40?w=700&q=80&auto=format&fit=crop', 'Diseño robusto y protagonista. Para quienes buscan una pieza de carácter que no pase desapercibida.', '<p>El anillo grueso de cobre es una declaración. No es una joya discreta ni minimalista — es una pieza que ocupa espacio, que genera presencia, que invita a preguntas. Para quienes entienden el estilo como una forma de comunicar quiénes son sin decir una sola palabra.</p><p>Elaborado a mano en cobre macizo, su grosor lo convierte en un objeto con peso real, con textura real, con historia real. Cada uno tiene marcas de herramienta, ondulaciones sutiles, imperfecciones que son exactamente lo que lo hace auténtico. No se fabrica en serie. Se trabaja de a uno.</p><p>Con el tiempo desarrolla una pátina — un cambio de color natural que lo hace más profundo y más interesante. Es una joya para personas que valoran lo que mejora con el paso del tiempo.</p>', 11),
('cadena-amatista', 'Cadena Amatista', 'joyeria', 'Cadenas', 12000, 10, 'active', false, 'https://images.unsplash.com/photo-1632980205460-e490e885e848?w=700&q=80&auto=format&fit=crop', 'Amatista natural en cadena delicada. Calma y claridad cerca del corazón todo el día.', '<p>Llevar amatista en una cadena significa tener esa energía calmante y clarificadora sobre el pecho, cerca del corazón y la garganta, durante toda la jornada. A diferencia de un anillo, el colgante descansa sobre el chakra del corazón y el chakra de la garganta — dos centros claves para la comunicación emocional y la claridad mental.</p><p>La piedra natural tiene su peso, su temperatura, su textura. Quien usa esta cadena con regularidad describe una sensación de mayor serenidad y de pensamientos más ordenados. No es inmediata ni dramática — es gradual, como el trabajo de las mejores cosas.</p><p>La combinación de la piedra violeta con una cadena fina crea una joya que es a la vez discreta y completamente significativa. Puede usarse sola o layered con otras cadenas. Se adapta a cualquier estilo y a cualquier momento del día.</p>', 12),
('cadena-labradorita', 'Cadena Labradorita', 'joyeria', 'Cadenas', 12000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'Los destellos únicos de la labradorita en colgante. Intuición y magia llevada con elegancia.', '<p>En formato colgante, la labradorescencia de esta piedra — ese fenómeno de luz iridiscente que la convierte en un universo en miniatura — es aún más visible y llamativa que en un anillo. Cada vez que la luz cambia de ángulo, la piedra responde con un nuevo destello.</p><p>Su energía trabaja sobre el tercer ojo, amplificando la intuición y protegiendo el campo energético de influencias externas. Es la cadena ideal para quienes trabajan de manera creativa, intuitiva o espiritual y necesitan mantener esa claridad durante todo el día.</p><p>Una pieza para personas que saben que lo más valioso no siempre se ve a primera vista — y que aprecian las cosas que cambian según cómo las mirás.</p>', 13),
('cadena-obsidiana', 'Cadena Obsidiana', 'joyeria', 'Cadenas', 11000, 10, 'active', false, 'https://images.unsplash.com/photo-1609216970378-ce61cd74a187?w=700&q=80&auto=format&fit=crop', 'Escudo energético constante. La obsidiana volcánica más cerca del corazón.', '<p>Llevar obsidiana en una cadena es crear un escudo energético que descansa sobre el pecho durante toda la jornada. El chakra del corazón — uno de los más vulnerables a las influencias del entorno — queda protegido por la energía densa y ancladora de esta piedra volcánica.</p><p>Es la cadena más elegida por personas que trabajan en entornos de alta exposición emocional: terapeutas, docentes, trabajadores de la salud, personas que absorben fácilmente las emociones ajenas. La obsidiana actúa como filtro — deja pasar lo que nutre y bloquea lo que no sirve.</p><p>En negro profundo y brillante, tiene además una presencia estética poderosa. Simple, directa, sin ornamentos innecesarios. Una pieza que dice mucho sin decir nada.</p>', 14),
('cadena-turmalina', 'Cadena Turmalina', 'joyeria', 'Cadenas', 13000, 10, 'active', true, 'https://images.unsplash.com/photo-1609216970378-ce61cd74a187?w=700&q=80&auto=format&fit=crop', 'Turmalina negra para protección máxima. La más potente de las piedras protectoras en uso diario.', '<p>La turmalina negra es, para muchos, la piedra protectora más poderosa que existe. A diferencia de la obsidiana — que absorbe — la turmalina repele activamente las energías densas y negativas. Es un escudo activo, no solo una barrera pasiva.</p><p>Funciona como un campo electromagnético personal: devuelve al emisor las energías que no pertenecen al portador, mantiene el campo áurico limpio y fortalece la conexión con la tierra. Es la elección de quienes viven en entornos urbanos de alta densidad energética, o que se relacionan con muchas personas distintas a lo largo del día.</p><p>En cadena, su acción es constante. Una sola pieza puede transformar la forma en que uno transita los espacios públicos, las interacciones difíciles y los momentos de mayor exigencia.</p>', 15),
('cadena-rodocrosita', 'Cadena Rodocrosita', 'joyeria', 'Cadenas', 13000, 10, 'active', false, 'https://images.unsplash.com/photo-1593259213062-57b0ce5906cf?w=700&q=80&auto=format&fit=crop', 'La Rosa del Inca en formato cadena. Amor propio y sanación emocional con elegancia.', '<p>La rodocrosita argentina en su versión más elegante: una cadena que descansa sobre el corazón, enviando su energía directamente al chakra del amor. Sus bandas rosas y blancas, visibles incluso en el pequeño colgante, son inconfundiblemente bellas.</p><p>Es uno de los regalos más significativos de nuestra colección — no porque sea el más costoso, sino porque llega en los momentos más importantes: cuando alguien querido está transitando un proceso de sanación, cuando se celebra un logro personal, cuando se quiere decir "te veo, te acompaño, te quiero".</p><p>El amor propio no es un destino. Es una práctica diaria. Y a veces, un objeto bello que se lleva cerca del corazón es el recordatorio que alguien necesita para seguir cultivándolo.</p>', 16),
('cadena-malaquita', 'Cadena Malaquita', 'joyeria', 'Cadenas', 13000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'Las espirales verdes de la malaquita como colgante. Transformación y crecimiento constante.', '<p>La malaquita en formato cadena es una declaración de que se está en movimiento — en un proceso de cambio consciente. Sus espirales verdes, visibles en el colgante, son el patrón más hipnótico de todo el reino mineral. Y como no hay dos iguales, cada pieza cuenta una historia única.</p><p>Llevada sobre el pecho, trabaja directamente sobre el chakra del corazón amplificando tanto lo que está bien como lo que pide atención. Es una piedra honesta: no esconde, revela. Por eso es ideal para quienes están listos para ver con claridad y dar el siguiente paso en su crecimiento.</p><p>Combina con prendas en tonos naturales — verdes, blancos, crudos — y también funciona como punto focal sobre tonos oscuros. Una pieza que no necesita competir con nada para ser protagonista.</p>', 17),
('cadena-jade', 'Cadena Jade', 'joyeria', 'Cadenas', 12000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'Jade natural para atraer prosperidad y equilibrio. Un clásico de cinco mil años en tu cuello.', '<p>Llevar jade en una cadena es una práctica con más de cinco mil años de historia. En la China imperial, el jade se usaba en collares ceremoniales que se transmitían de generación en generación. Se creía que quien lo portaba cerca del corazón recibía su protección durante toda la vida.</p><p>Hoy, su energía sigue siendo la misma: equilibrio, prosperidad, protección y sabiduría. Su verde natural tiene una elegancia que trasciende modas y tendencias. Es un mineral que nunca pasa de moda porque nunca estuvo de moda — siempre fue atemporal.</p><p>Una pieza para quienes valoran la profundidad por encima de la novedad. Una joya que puede durar toda una vida y seguir siendo exactamente lo que necesitás.</p>', 18),
('cadena-pirita', 'Cadena Pirita', 'joyeria', 'Cadenas', 14000, 10, 'active', false, 'https://images.unsplash.com/photo-1650208532541-572697b3dd40?w=700&q=80&auto=format&fit=crop', 'El dorado de la abundancia. Pirita para activar la voluntad, la confianza y la prosperidad real.', '<p>La pirita fue llamada "el oro de los tontos" — pero los únicos que se equivocaron fueron quienes la descartaron. Su brillo metálico dorado, su peso real, su densidad mineral no tienen nada de falso. Y su energía tampoco: la pirita activa el plexo solar, el centro de la voluntad, la acción y la confianza.</p><p>Llevarla en una cadena es tener ese combustible encendido durante toda la jornada. Personas que la usan regularmente reportan mayor energía para iniciar proyectos, más confianza en sus decisiones y una apertura mayor hacia las oportunidades que se presentan. No es magia — es intención sostenida.</p><p>Estéticamente, su dorado metálico es llamativo sobre cualquier prenda. Va con todo: tejidos naturales, colores oscuros, estilos formales e informales. Es la cadena ideal para quienes combinan la espiritualidad con la ambición concreta.</p>', 19),
('cadena-citrino', 'Cadena Citrino', 'joyeria', 'Cadenas', 13000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'La piedra del sol. Citrino para alegría permanente, abundancia y energía solar en el día a día.', '<p>El citrino captura la luz del sol en su interior y la irradia de forma constante. Su amarillo dorado — que va desde el más pálido hasta el naranja ámbar — tiene una calidez visual que se percibe incluso antes de conocer sus propiedades.</p><p>Es conocida como la piedra de la alegría y la abundancia por dos razones: primero, porque tiene la particularidad única entre los minerales de no acumular energías negativas sino transmutarlas. Segundo, porque trabaja sobre el plexo solar activando la confianza, la creatividad y la apertura hacia lo que viene. Una piedra que mira hacia adelante.</p><p>Llevarla en una cadena cerca del pecho convierte cada jornada en una práctica de liviandad y gratitud. Ideal para personas que tienden al pesimismo, la ansiedad o el agotamiento — el citrino recuerda que también existe la luz.</p>', 20),
('cadena-cuarzo-rosa', 'Cadena Cuarzo Rosa', 'joyeria', 'Cadenas', 12000, 10, 'active', false, 'https://images.unsplash.com/photo-1593259213062-57b0ce5906cf?w=700&q=80&auto=format&fit=crop', 'El amor cerca del corazón. Cuarzo rosa para el amor propio y las relaciones conscientes.', '<p>La cadena de cuarzo rosa es de los regalos más elegidos de nuestra colección — y no es casualidad. Su energía amorosa y suave es universal: no hay edad, no hay momento de vida, no hay persona para quien el cuarzo rosa no sea exactamente lo que necesita.</p><p>Descansando sobre el pecho, trabaja directamente sobre el chakra del corazón: abre, suaviza, sana y expande. Es una presencia constante de amor — no el amor dramático o urgente, sino el amor calmo, seguro y profundo.</p><p>Viene con packaging especial para regalo. Podés agregar una tarjeta personalizada escrita a mano. Es la cadena para el cumpleaños de alguien importante, para decirle a alguien que importa, para regalarse a uno mismo en un momento de cuidado personal.</p>', 21),
('cadena-aguamarina', 'Cadena Aguamarina', 'joyeria', 'Cadenas', 15000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'El azul del océano en una piedra. Aguamarina para la comunicación honesta y la serenidad profunda.', '<p>La aguamarina captura el azul del mar en todas sus variaciones: desde el celeste más suave hasta el azul profundo del océano abierto. Su nombre mismo — agua marina — describe lo que es: un fragmento del mar cristalizado en piedra.</p><p>Los marineros griegos y romanos la llevaban como protección en el mar. Creían que era el tesoro de las sirenas y que calmar el océano. Hoy se la asocia a la comunicación: abre el chakra de la garganta, facilita la expresión honesta y clarifica el pensamiento antes de hablar.</p><p>Es la piedra ideal para quienes hablan en público, enseñan, negocian o simplemente quieren comunicar con más claridad y desde un lugar más tranquilo. Una voz que viene desde la serenidad llega siempre más lejos.</p>', 22),
('cadena-lapislazuli', 'Cadena Lapislázuli', 'joyeria', 'Cadenas', 14000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'La piedra de los faraones. Lapislázuli para la sabiduría, intuición y comunicación espiritual elevada.', '<p>Durante tres mil años, el lapislázuli fue la piedra más valiosa del mundo — más que el oro y las esmeraldas. Los faraones egipcios la usaban en sus máscaras funerarias. Cleopatra la usaba triturada como sombra de ojos. Los reyes de Mesopotamia la grababan en sus sellos. Ninguna otra piedra tiene una historia de poder y espiritualidad tan extensa y documentada.</p><p>Su azul profundo tachonado de destellos dorados de pirita — que remedan un cielo estrellado — es inconfundible y de una belleza que no envejece. En el plano energético, activa simultáneamente el tercer ojo (intuición) y el chakra de la garganta (comunicación), creando un canal entre la percepción y la expresión.</p><p>Es la cadena para quienes buscan hablar desde la sabiduría — no desde la reacción. Para quienes enseñan, lideran, crean o simplemente quieren que sus palabras tengan peso y claridad.</p>', 23),
('cadena-corazon-amatista', 'Cadena Corazón Amatista', 'joyeria', 'Cadenas Corazón', 13000, 10, 'active', false, 'https://images.unsplash.com/photo-1632980205460-e490e885e848?w=700&q=80&auto=format&fit=crop', 'El símbolo del amor tallado en amatista natural. Calma, amor y conexión espiritual en una sola pieza.', '<p>El corazón es el símbolo universal del amor — en todas las culturas, en todos los tiempos. Cuando se talla en amatista, esa forma adquiere una dimensión adicional: la de la calma, la claridad y la conexión con algo más profundo que la emoción inmediata. Es el amor sereno, el amor que piensa antes de hablar.</p><p>La piedra en forma de corazón descansa sobre el chakra del mismo nombre cuando se lleva en cadena. La combinación es poderosa: el símbolo y la energía de la piedra se potencian mutuamente, creando una pieza que trabaja en ambos planos — el simbólico y el energético.</p><p>Como regalo, es de los más significativos que existe. Dice exactamente lo que necesita decir sin necesitar ninguna explicación adicional.</p>', 24),
('cadena-corazon-citrino', 'Cadena Corazón Citrino', 'joyeria', 'Cadenas Corazón', 14000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'Citrino dorado en forma de corazón. Alegría, amor y abundancia como intención diaria.', '<p>El citrino amarillo dorado tallado en corazón es una pieza de una alegría visual inmediata. Su color cálido y su forma reconocible crean una joya que genera una sonrisa antes de que alguien sepa lo que es. Y eso, en sí mismo, ya dice algo sobre la energía del citrino: alegría inmediata, sin rodeos.</p><p>Combina la energía solar del citrino — que activa la confianza, la creatividad y la abundancia — con el símbolo del amor. El resultado es una intención hermosa: amar desde la alegría, desde la confianza, desde la abundancia. No desde el miedo ni desde la escasez.</p><p>Para regalarse o para regalar. Para los días que necesitan un poco más de luz.</p>', 25),
('cadena-corazon-jade', 'Cadena Corazón Jade', 'joyeria', 'Cadenas Corazón', 13000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'Jade verde natural tallado en corazón. Amor, prosperidad y equilibrio en una sola pieza.', '<p>En la cultura china, el jade y el amor son inseparables. Se lo regalaban los amantes, lo usaban las novias, lo transmitían las madres a sus hijas. Esta tradición de miles de años tiene una razón energética simple: el jade trabaja sobre el chakra del corazón atrayendo amor genuino, prosperidad compartida y equilibrio en los vínculos.</p><p>Tallado en corazón, esa intención se vuelve explícita y visible. Una pieza que no necesita explicación: la forma habla, la piedra trabaja, el significado está ahí para quien quiera recibirlo.</p><p>Verde natural con sus variaciones propias de cada piedra. Elegancia sin ostentación. Una joya que dura toda la vida.</p>', 26),
('cadena-corazon-obsidiana', 'Cadena Corazón Obsidiana', 'joyeria', 'Cadenas Corazón', 12000, 10, 'active', false, 'https://images.unsplash.com/photo-1609216970378-ce61cd74a187?w=700&q=80&auto=format&fit=crop', 'Obsidiana volcánica en corazón. Proteger el corazón desde la fuerza, no desde el miedo.', '<p>Un corazón de obsidiana negra es una paradoja hermosa: el símbolo del amor tallado en la piedra de la protección. Pero en realidad, tiene sentido perfecto. La obsidiana protege el corazón — no cerrándolo, sino fortaleciéndolo. No es el corazón blindado que no deja entrar nada. Es el corazón que sabe cuándo abrir y cuándo cuidarse.</p><p>En negro brillante, la forma de corazón adquiere una elegancia oscura y sofisticada. No es una joya delicada ni romántica en el sentido convencional — es una pieza de carácter, para quienes aman desde la fuerza y el autoconocimiento.</p><p>Ideal para quienes están atravesando procesos de sanación emocional o aprendiendo a poner límites desde el amor.</p>', 27),
('cadena-corazon-lapislazuli', 'Cadena Corazón Lapislázuli', 'joyeria', 'Cadenas Corazón', 15000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'El azul real de los faraones en forma de corazón. Amor, sabiduría y comunicación espiritual.', '<p>El lapislázuli tiene el azul más profundo y real del reino mineral. Tallado en corazón, esa profundidad se vuelve íntima y cercana. Es un corazón que piensa, que percibe, que comunica desde la sabiduría. El amor del lapislázuli no es impulsivo — es maduro, consciente y elevado.</p><p>Sus destellos dorados de pirita sobre el azul noche son visibles incluso en el pequeño colgante, creando una pieza de una belleza completamente única. Combina el símbolo universal del amor con la energía más elevada del reino mineral.</p><p>Para quienes buscan amar y ser amados con consciencia. Para quienes entienden que el amor más profundo también implica verdad, sabiduría y una comunicación honesta.</p>', 28),
('cadena-corazon-ojo-tigre', 'Cadena Corazón Ojo de Tigre', 'joyeria', 'Cadenas Corazón', 13000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'Ojo de tigre en corazón. El amor desde la confianza, el poder personal y la claridad mental.', '<p>El ojo de tigre tiene un efecto visual hipnótico: sus bandas doradas y marrones parecen moverse cuando la luz cambia de ángulo — el fenómeno llamado chatoyance, o ojo de gato. Tallado en corazón, ese movimiento de luz se convierte en algo casi vivo, casi mágico.</p><p>Su energía trabaja sobre el plexo solar y el chakra raíz, activando la confianza, el poder personal y el coraje. Es el amor desde la fortaleza: no el amor que se achica y se adapta, sino el amor que se mantiene en pie, que sabe lo que vale y lo que merece.</p><p>Para quienes están aprendiendo a amarse desde un lugar de más poder propio. Para quienes quieren amar sin perder su centro.</p>', 29),
('nudo-de-bruja', 'Amuleto Nudo de Bruja', 'joyeria', 'Amuletos', 11000, 10, 'active', false, 'https://images.unsplash.com/photo-1609216970378-ce61cd74a187?w=700&q=80&auto=format&fit=crop', 'Símbolo ancestral de protección y magia femenina. Un amuleto tejido a mano con intención.', '<p>El nudo de bruja — también conocido como nudo de la bruja o witch knot — es uno de los símbolos de protección más antiguos de la tradición europea. Se encuentran grabados en piedras de la era vikinga, en amuletos medievales, en los umbrales de las casas de campo de Escocia e Irlanda. Un símbolo que atravesó milenios porque funciona: su patrón sin principio ni fin no tiene entrada para energías no deseadas.</p><p>Este amuleto está confeccionado a mano. Cada nudo tiene su intención: proteger quien lo lleva, mantener su campo energético limpio y crear un escudo de poder personal. No es decoración — es práctica espiritual llevada puesta.</p><p>Para quienes se conectan con la tradición de las mujeres sabias, con la magia de lo ancestral y con el poder de los símbolos que trascienden el tiempo.</p>', 30),
('trisquel-celta', 'Amuleto Trisquel Celta', 'joyeria', 'Amuletos', 11000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'El espiral triple celta. Símbolo del movimiento eterno: vida, muerte y renacimiento.', '<p>El trisquel — tres espirales unidas en un solo centro — es uno de los símbolos más poderosos de la tradición celta. Aparece grabado en la piedra de Newgrange, Irlanda, construida hace más de cinco mil años — antes de Stonehenge, antes de las pirámides. Es uno de los símbolos más antiguos creados por seres humanos.</p><p>Su significado es múltiple y profundo: representa los tres mundos (tierra, mar, cielo), las tres etapas de la vida (nacimiento, vida, muerte), las tres fases de la luna (creciente, llena, menguante) y el movimiento eterno del tiempo. Cada espiral fluye hacia el centro y desde el centro, en un ciclo sin fin.</p><p>Llevarlo es conectarse con esa energía de movimiento y renovación permanente. Un recordatorio de que nada se detiene, de que cada final es el principio de algo nuevo, de que estamos siempre en tránsito hacia algo mejor.</p>', 31),
('metatron', 'Amuleto Cubo de Metatrón', 'joyeria', 'Amuletos', 13000, 10, 'active', false, 'https://images.unsplash.com/photo-1609216970378-ce61cd74a187?w=700&q=80&auto=format&fit=crop', 'Geometría sagrada que contiene todas las formas del universo. El símbolo más completo de la creación.', '<p>El Cubo de Metatrón es uno de los símbolos más complejos y poderosos de la geometría sagrada. Dentro de su estructura están contenidas todas las figuras geométricas fundamentales del universo: el tetraedro, el cubo, el octaedro, el dodecaedro y el icosaedro — los llamados sólidos platónicos, que según Platón son las formas básicas de toda la materia.</p><p>En la tradición judía y cristiana, Metatrón es el ángel del universo, el guardián de los registros akáshicos, el mensajero entre lo divino y lo humano. Su cubo representa el equilibrio absoluto entre todos los elementos y fuerzas de la creación.</p><p>Llevarlo es recordar que existe un orden perfecto detrás del aparente caos. Es un ancla de equilibrio, una conexión con la inteligencia del universo y un símbolo de protección y armonía en todos los planos de la existencia.</p>', 32),
('camafeo-cornalina', 'Camafeo Cornalina', 'joyeria', 'Amuletos', 12000, 10, 'active', false, 'https://images.unsplash.com/photo-1593259213062-57b0ce5906cf?w=700&q=80&auto=format&fit=crop', 'Cornalina naranja en formato camafeo vintage. Vitalidad, creatividad y coraje en una pieza con historia.', '<p>El camafeo es una de las formas de joyería más antiguas del mundo — los griegos y los romanos los tallaban en ágata y cornalina para los anillos de los emperadores. Esta versión en cornalina naranja rescata esa estética vintage con una energía completamente contemporánea.</p><p>La cornalina es la piedra de la vitalidad y el coraje. Su naranja intenso — que va desde el melocotón hasta el rojo ladrillo — irradia una energía cálida y activadora. Trabaja sobre el chakra sacro, despertando la creatividad, la pasión y la energía vital. Es la piedra de los artistas, los emprendedores y quienes necesitan reavivar su fuego interior.</p><p>Como amuleto en formato camafeo, tiene además esa elegancia de lo antiguo que lo hace completamente especial y único en una colección de joyería.</p>', 33),
('medalla-pirita-labradorita', 'Medalla Pirita · Labradorita', 'joyeria', 'Amuletos', 16000, 10, 'active', true, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'El dúo más poderoso: intuición y abundancia en una sola medalla artesanal.', '<p>Esta medalla reúne dos de las piedras más buscadas de nuestra colección en una sola pieza: la labradorita, con su labradorescencia hipnótica, y la pirita, con su dorado metálico de abundancia. El resultado es una medalla que combina lo visual y lo energético de manera completamente original.</p><p>La labradorita aporta visión, intuición y protección del aura. La pirita aporta confianza, voluntad y apertura a la prosperidad. Juntas, son el amuleto perfecto para quienes están construyendo algo con intención: un proyecto, una carrera, una vida más alineada con sus valores.</p><p>Elaborada artesanalmente, cada medalla es única. El engaste, el tamaño de las piedras y la distribución del dorado y el iridiscente varía en cada pieza. Lo que nunca varía es la potencia de la combinación.</p>', 34),
('pulsera-obsidiana', 'Pulsera Obsidiana', 'joyeria', 'Pulseras', 7500, 10, 'active', true, 'https://images.unsplash.com/photo-1609216970378-ce61cd74a187?w=700&q=80&auto=format&fit=crop', 'Esferas de obsidiana volcánica para protección energética constante. La más elegida de la colección.', '<p>La pulsera de obsidiana es, por lejos, la más elegida de todo nuestro catálogo de joyería — y hay una razón para eso. Sus esferas de vidrio volcánico negro crean un campo de protección constante alrededor de quien la lleva. No es sutil ni discreta en su energía: trabaja de manera activa y directa.</p><p>En la muñeca izquierda —considerada receptiva— absorbe energías densas del entorno. En la muñeca derecha —considerada activa— crea un escudo ante lo que se proyecta hacia afuera. Muchas personas la usan en la muñeca izquierda para protegerse durante el día y la limpian regularmente dejándola bajo agua corriente o bajo la luna.</p><p>Sus esferas negras brillantes tienen además una estética fuerte y contemporánea. Combina con cualquier estilo — y se lleva sola o apilada con otras pulseras.</p>', 35),
('pulsera-cuarzo-rosa', 'Pulsera Cuarzo Rosa', 'joyeria', 'Pulseras', 7500, 10, 'active', false, 'https://images.unsplash.com/photo-1593259213062-57b0ce5906cf?w=700&q=80&auto=format&fit=crop', 'Esferas de cuarzo rosa. La pulsera del amor propio. Un regalo siempre acertado para cualquier ocasión.', '<p>La pulsera de cuarzo rosa tiene algo que pocas joyas tienen: una energía que se percibe incluso antes de saber lo que es. Su rosado suave y sus esferas perfectas generan una sensación de calma y ternura inmediata. Es pura energía amorosa en la muñeca.</p><p>Es la pulsera ideal para personas que están trabajando en el amor propio, la autoestima o la apertura emocional. También es perfecta para regalar — en cumpleaños, en momentos de apoyo, como gesto de cariño. El cuarzo rosa siempre llega en el momento indicado porque la energía del amor nunca está de más.</p><p>Viene con packaging especial. Se puede apilar con otras pulseras de piedras para crear combinaciones energéticas personalizadas.</p>', 36),
('pulsera-amatista', 'Pulsera Amatista', 'joyeria', 'Pulseras', 7500, 10, 'active', false, 'https://images.unsplash.com/photo-1632980205460-e490e885e848?w=700&q=80&auto=format&fit=crop', 'Esferas de amatista para calmar la mente y sostener el equilibrio emocional durante todo el día.', '<p>La pulsera de amatista es la aliada de los momentos de alta exigencia mental. Sus esferas violetas actúan como un ancla de serenidad durante la jornada — en la oficina, en los exámenes, en las conversaciones difíciles, en los momentos donde la mente tiende a acelerarse.</p><p>La amatista trabaja sobre los chakras de la corona y el tercer ojo, facilitando la claridad mental, la intuición y el equilibrio emocional. En formato pulsera, esa energía está en contacto directo con los meridianos de energía de la muñeca durante todo el tiempo que se lleva puesta.</p><p>Se combina perfectamente con la pulsera de cuarzo rosa (amor + calma) o con la pulsera de cristal (amplificación de la energía calmante). Una inversión en bienestar diario.</p>', 37),
('pulsera-cristal', 'Pulsera Cristal', 'joyeria', 'Pulseras', 7000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'Cuarzo cristal transparente. El amplificador universal que potencia cualquier piedra que lo acompañe.', '<p>El cuarzo cristal transparente es conocido como el "maestro sanador" en la tradición de la cristaloterapia — no porque cure todo, sino porque amplifica la energía de lo que lo rodea. Usado solo, actúa como un limpiador y clarificador del campo energético. Usado junto con otras piedras, potencia sus propiedades.</p><p>En formato pulsera de esferas transparentes, tiene una elegancia minimalista que combina con absolutamente todo. No llama la atención visualmente — trabaja en silencio. Pero su efecto es constante y profundo.</p><p>Es la pulsera ideal para combinar en stack con otras de la colección: potencia la protección de la obsidiana, amplifica el amor del cuarzo rosa, refuerza la calma de la amatista. Un multiplicador energético discreto y poderoso.</p>', 38),
('pulsera-7-chakras', 'Pulsera 7 Chakras', 'joyeria', 'Pulseras', 9500, 10, 'active', true, 'https://images.unsplash.com/photo-1609216970378-ce61cd74a187?w=700&q=80&auto=format&fit=crop', 'Siete piedras naturales, una por chakra. Equilibrio energético completo en una sola pulsera.', '<p>Los siete chakras son los siete centros de energía del cuerpo según la tradición yóguica de la India. Cada uno corresponde a un plano de la existencia — físico, emocional, creativo, amoroso, comunicativo, intuitivo y espiritual. Cuando todos están en equilibrio, la vida fluye. Cuando alguno está bloqueado, algo no fluye.</p><p>Esta pulsera reúne siete piedras naturales — una por cada chakra — para invitar a ese equilibrio durante todo el día. Las piedras varían según disponibilidad pero siempre representan: granate o ágata roja (raíz), cornalina (sacro), citrino (plexo solar), aventurina o cuarzo rosa (corazón), aquamarina o sodalita (garganta), lapislázuli o amatista (tercer ojo), cuarzo cristal o amatista clara (corona).</p><p>Es la pulsera más completa de nuestra colección — un recordatorio diario de la integración y el equilibrio en todos los planos de la vida.</p>', 39),
('pulsera-calma', 'Pulsera Calma', 'joyeria', 'Pulseras', 9000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'Curaduría especial para el estrés y la ansiedad. Tres piedras seleccionadas para sostener la serenidad.', '<p>La pulsera Calma es nuestra curaduría más pensada. Tres piedras seleccionadas específicamente por sus propiedades calmantes, combinadas en una sola pulsera: amatista (calma mental), aguamarina (serenidad de expresión) y selenita o cuarzo blanco (limpieza y paz).</p><p>El resultado es una pulsera que trabaja en simultáneo sobre la mente, las emociones y el campo energético, creando una sensación de serenidad sostenida. No es una solución instantánea — es un apoyo constante, como tener un recordatorio físico de que la calma es siempre posible.</p><p>Ideal para momentos de estrés laboral, ansiedad, insomnio o cualquier período de alta exigencia emocional. Para usarla antes de una situación difícil, durante la meditación o simplemente como compañía diaria.</p>', 40),
('pulsera-cobre-india', 'Pulsera Cobre India', 'joyeria', 'Pulseras', 8500, 10, 'active', false, 'https://images.unsplash.com/photo-1650208532541-572697b3dd40?w=700&q=80&auto=format&fit=crop', 'Diseño inspirado en la tradición espiritual india. Cobre artesanal con grabados únicos y energía ancestral.', '<p>La India tiene una de las tradiciones de joyería en cobre más ricas del mundo. El cobre no es solo un metal — en la tradición ayurvédica y espiritual india, es un conductor de prana (energía vital) que equilibra los tres doshas y fortalece el sistema inmune. Por eso los yoguis y los saddhus de la India lo han llevado durante siglos.</p><p>Esta pulsera rescata esa tradición con un diseño contemporáneo: grabados inspirados en motivos de la cultura india, elaborados artesanalmente. Cada una tiene su propio patrón — ningún grabado es idéntico al anterior.</p><p>El cobre desarrolla con el tiempo una pátina que lo hace más rico visualmente. Es una pulsera que mejora con el uso, que cuenta la historia de quien la lleva. Para personas que valoran la artesanía, la tradición y los objetos con alma.</p>', 41),
('potus-matizado', 'Potus Matizado', 'plantas', 'Interior', 4500, 10, 'active', false, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'La planta de interior más resiliente y decorativa. Hojas matizadas únicas y virtualmente indestructible.', '<p>El potus matizado es, sin duda, una de las plantas de interior más extraordinarias que existen. No por su rareza — sino exactamente por lo contrario: es extraordinariamente accesible. Tolera la falta de luz, el olvido del riego, el calor excesivo y el frío moderado con una elegancia que ninguna otra planta tiene. Y a cambio de todo eso, da hojas únicas.</p><p>Sus hojas verdes con matices amarillos o claros son el resultado de variaciones naturales en la cantidad de clorofila. Ninguna es exactamente igual a la anterior. La planta que recibís crece, se ramifica, genera tallos colgantes que pueden llegar a metros de longitud si se los deja libres.</p><p>Purifica el aire — la NASA la incluye en su lista de plantas que filtran tóxicos del ambiente — y no pide casi nada a cambio. Para dormitorios, baños con algo de luz, oficinas, estudios: en cualquier espacio con un poco de luz indirecta, el potus prospera.</p>', 42),
('potus-joy', 'Potus Joy', 'plantas', 'Interior', 4500, 10, 'active', false, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'Hojas luminosas y crecimiento vigoroso. La variedad más alegre del potus para espacios oscuros.', '<p>El Potus Joy se distingue del matizado por sus hojas más claras, casi amarillo limón en las zonas de mayor luz. Esa luminosidad es especialmente valiosa en espacios donde la luz natural es escasa: pasillos, baños interiores, escritorios lejos de las ventanas. La planta literalmente ilumina el espacio con su color.</p><p>Tiene un crecimiento más vigoroso que el potus estándar, lo que lo hace ideal para ese efecto de planta colgante que cae en cascada desde una repisa o macetero colgante. Con el tiempo, sus tallos pueden alcanzar el metro y medio o más de longitud.</p><p>Tan fácil de cuidar como cualquier potus — riego moderado, sin sol directo — pero con una presencia visual más llamativa e intensa. Para espacios que necesitan vida y color sin complicaciones de mantenimiento.</p>', 43),
('potus-variegado', 'Potus Variegado', 'plantas', 'Interior', 6500, 10, 'active', false, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'La variedad más buscada. Hojas mitad verde, mitad blanco cremoso — una rareza genética real.', '<p>El potus variegado es el objeto de deseo de todos los amantes de las plantas de interior. Sus hojas — mitad verde oscuro profundo, mitad blanco cremoso puro — no son el resultado de ningún tratamiento ni proceso artificial. Son el resultado de una mutación genética que elimina la clorofila de parte de la célula vegetal. Cada hoja que emerge es un acto de naturaleza caprichosa: nunca saber exactamente cómo será la siguiente.</p><p>Por esa razón, crece más lento que el potus estándar: las zonas blancas no fotosintestizan, lo que ralentiza el crecimiento general. Eso también la hace más valiosa — se necesita más tiempo para producir cada planta de tamaño.</p><p>En decoración, es la planta que hace que cualquier espacio parezca curado y sofisticado. No es un accidente que aparezca en las páginas de las mejores revistas de interiorismo del mundo. Requiere algo más de luz que el potus común para mantener su variegación.</p>', 44),
('espada-san-jorge', 'Espada de San Jorge', 'plantas', 'Interior', 5500, 10, 'active', true, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'La planta protectora por excelencia. Purifica el aire, requiere mínimo cuidado y protege el hogar.', '<p>La Sansevieria trifasciata — espada de San Jorge o lengua de suegra — es, sin exagerar, una de las plantas más extraordinarias del mundo. Puede sobrevivir semanas sin agua. Tolera la oscuridad casi total. Resiste las heladas leves. Es prácticamente indestructible. Y a cambio de todo ese estoicismo, purifica el aire de manera excepcional.</p><p>La NASA la incluyó en su estudio sobre plantas purificadoras como una de las más efectivas para filtrar formaldehído, benceno y tricloroetileno del aire interior. También tiene la particularidad única de producir oxígeno y absorber CO2 durante la noche — a la inversa del resto de las plantas. Ideal en dormitorios.</p><p>En el plano espiritual y de las tradiciones populares de Brasil, África y el Caribe, la espada de San Jorge es la planta protectora del hogar por excelencia. Se coloca en la entrada para absorber las energías negativas que intentan ingresar. Su forma de espada no es solo estética — es simbólica.</p>', 45),
('violeta-alpes', 'Violeta de los Alpes', 'plantas', 'Interior', 4000, 10, 'active', false, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'Floración intensa y duradera. Rosas, malvas y blancos que alegran cualquier espacio con luz.', '<p>La Cyclamen — violeta de los Alpes — tiene algo que pocas plantas de interior tienen: flores. Muchas plantas se eligen por sus hojas, pero la violeta de los Alpes ofrece una floración abundante y prolongada en una paleta de colores que va desde el blanco más puro hasta el rosa oscuro y el malva intenso.</p><p>Florece principalmente en otoño, invierno y primavera — los meses en que más falta hace color en el hogar. Y cuando florece, no lo hace a medias: se cubre de flores simultáneamente, creando una explosión de color que transforma cualquier ventana, escritorio o mesa de living.</p><p>Requiere algo más de atención que el potus — riego regular sin exceso, buena luz sin sol directo intenso, temperatura fresca. Pero esa atención se recompensa con meses de floración que pocas otras plantas de interior pueden igualar.</p>', 46),
('costilla-adan', 'Costilla de Adán', 'plantas', 'Decorativas', 8500, 10, 'active', true, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'La Monstera más icónica del mundo. Hojas fenestradas que transforman radicalmente cualquier espacio.', '<p>La Monstera deliciosa — costilla de Adán — es la planta más fotografiada del mundo de las plantas de interior. Y no es moda pasajera: lleva décadas siendo la referencia del interiorismo con plantas porque su impacto visual es genuinamente difícil de igualar. Esas hojas verdes profundas, grandes como platos, con sus perforaciones características, crean una silueta que es inmediatamente reconocible y completamente fascinante.</p><p>Las perforaciones — llamadas fenestras — no son un accidente ni una enfermedad. Son una adaptación evolutiva: en su hábitat natural, en los bosques tropicales de México y América Central, las fenestras permiten que la lluvia y el viento pasen a través de las hojas sin dañarlas. La naturaleza como diseñadora perfecta.</p><p>En el hogar, una Monstera bien cuidada puede alcanzar hojas de más de medio metro. Requiere buena luz indirecta, riego moderado y una maceta con espacio para crecer. A cambio, transforma cualquier rincón en un espacio que parece pensado por un diseñador de interiores.</p>', 47),
('costilla-adan-tupida', 'Costilla de Adán Tupida', 'plantas', 'Decorativas', 12000, 10, 'active', true, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'La Monstera en versión voluminosa y exuberante. Múltiples tallos para una presencia de selva.', '<p>La Costilla de Adán Tupida es la versión más exuberante de la Monstera deliciosa. Mientras la versión estándar tiene uno o dos tallos principales, la tupida tiene múltiples brotes que crecen juntos creando una masa densa de hojas fenestradas que se superponen y crean una profundidad visual asombrosa.</p><p>Si la Monstera estándar es elegante, la tupida es opulenta. Es la planta que convierte un rincón vacío en algo que parece sacado de una revista de interiorismo de lujo tropical. Cada hoja en una posición diferente, a distinta altura, capturando la luz de maneras distintas.</p><p>Requiere el mismo cuidado que la Monstera estándar — quizás algo más de fertilización por la cantidad de follaje — pero el resultado visual justifica completamente el esfuerzo extra. Una inversión en verde que se percibe desde la puerta.</p>', 48),
('limon-4-estaciones', 'Limón 4 Estaciones', 'plantas', 'Frutales', 9500, 10, 'active', false, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'Limones todo el año en maceta. Aroma cítrico incomparable y frutos frescos en tu balcón o terraza.', '<p>Hay pocas experiencias en jardinería tan satisfactorias como cosechar un limón de tu propio árbol. El limón 4 estaciones hace eso posible incluso en departamento: crece en maceta grande y fructifica de manera continua durante todo el año, sin importar la estación.</p><p>El aroma al florecer — esas flores blancas pequeñas y perfumadas que preceden a cada camada de frutos — es uno de los aromas más limpios y cítricos que existen. Llena el balcón o la terraza durante días cada vez que florece. Un privilegio sensorial que no tiene precio.</p><p>Necesita mucho sol directo (mínimo 6 horas), riego regular y fertilización cada 30-45 días con fertilizante para cítricos. Con esos cuidados, puede dar frutos durante décadas. Un árbol frutal en maceta es un proyecto de largo plazo que mejora con el tiempo.</p>', 49),
('mandarina-4-estaciones', 'Mandarina 4 Estaciones', 'plantas', 'Frutales', 9500, 10, 'active', false, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'Mandarinas dulces en maceta durante todo el año. Aroma floral intenso y frutos de color vibrante.', '<p>El mandarine es el cítrico más alegre. Sus frutos naranjas brillantes son visualmente exuberantes — un árbol cargado de mandarinas en una terraza es una imagen de abundancia pura. Y el aroma de sus flores, más dulce e intenso que el limón, es verdaderamente embriagante.</p><p>La variedad 4 estaciones asegura producción continua: no hay que esperar el otoño para tener frutos. El árbol va dando en oleadas a lo largo de todo el año, con períodos de floración que preceden cada camada. Perfecto para balcones y terrazas con buena exposición solar.</p><p>Requiere los mismos cuidados que cualquier cítrico: mucho sol, riego regular sin exceso de agua, fertilización cada mes y medio. La inversión de tiempo es mínima comparada con el placer de cosechar mandarinas propias.</p>', 50),
('naranjo-4-estaciones', 'Naranjo 4 Estaciones', 'plantas', 'Frutales', 9500, 10, 'active', false, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'El naranjo compacto para maceta. Azahar perfumado y naranjas propias en balcón o patio.', '<p>El azahar — la flor del naranjo — tiene uno de los aromas más codiciados del mundo. Es el perfume de los jardines mediterráneos, de las bodas tradicionales, de los atardeceres de Andalucía y el Magreb. Tener un naranjo en flor en el balcón es tener ese privilegio al alcance de la mano.</p><p>El naranjo 4 estaciones es compacto y perfectamente adaptado para maceta. Fructifica de manera continua, dando oleadas de frutos naranjas brillantes a lo largo del año. Cada fruto que se cosecha es una pequeña satisfacción que se acumula en placer cotidiano.</p><p>Como árbol decorativo, su follaje verde oscuro brillante y sus frutos coloridos lo convierten en uno de los elementos más elegantes para terrazas y patios. Un árbol de naranjos bien cuidado embellece cualquier espacio exterior.</p>', 51),
('ciruelo', 'Ciruelo', 'plantas', 'Frutales', 10000, 10, 'active', false, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'Ciruelo para jardín o maceta grande. Flores primaverales espectaculares y ciruelas dulces en verano.', '<p>El ciruelo tiene dos momentos cumbre en el año que justifican completamente su lugar en cualquier jardín o terraza grande. El primero es la floración primaveral: antes incluso de que salgan las hojas, el árbol se cubre de flores rosas o blancas que son un espectáculo visual único. El segundo es la fructificación estival: ciruelas dulces, jugosas, que se cosechan directamente del árbol.</p><p>Requiere más espacio que los cítricos — es ideal para jardín o maceta muy grande en terraza amplia. A cambio, ofrece esa doble fiesta visual de flores y frutos que pocos árboles pueden dar. También es uno de los árboles frutales más resistentes para el clima del Río de la Plata.</p>', 52),
('duraznero', 'Duraznero', 'plantas', 'Frutales', 10000, 10, 'active', false, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'Duraznos frescos y floración rosa intensa. Un árbol que transforma cualquier jardín en verano.', '<p>El duraznero florece en primavera con una explosión de rosa intenso que es genuinamente espectacular. Sus flores pequeñas y densas cubren todas las ramas antes de que aparezcan las hojas, creando una imagen que se graba en la memoria. Y luego, en verano, llegan los duraznos.</p><p>Hay algo completamente particular en comer un durazno cosechado directamente del árbol, maduro por el sol real, sin cadena de frío ni viaje largo. Un durazno propio en plena madurez es una de las experiencias más simples y perfectas del verano.</p><p>Requiere jardín o maceta muy grande. Necesita sol pleno y buen drenaje. Es uno de los árboles frutales más agradecidos para el clima templado de Argentina.</p>', 53),
('parra-uva', 'Parra de Uva', 'plantas', 'Frutales', 11000, 10, 'active', false, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'La parra como elemento de jardín. Sombra natural, uvas propias y una estética completamente única.', '<p>La parra de uva es mucho más que un frutal: es un elemento arquitectónico de jardín. Sus ramas trepadoras pueden cubrir pérgolas, muros y estructuras creando una sombra natural y viva que cambia según la estación. En verano, sus hojas grandes y densas crean espacios frescos. En otoño, se tiñen de rojos y amarillos antes de caer.</p><p>Y después están las uvas. Cosechar un racimo de tu propia parra — ya sean uvas de mesa para comer o variedades para elaborar vino casero — es una experiencia que conecta con miles de años de cultura humana alrededor de la vid.</p><p>Requiere estructura para trepar, suelo bien drenado y poda anual. Es un proyecto de varios años donde el resultado mejora cada temporada.</p>', 54),
('quinoto', 'Quinoto', 'plantas', 'Frutales', 9000, 10, 'active', false, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'El cítrico más decorativo. Frutos naranjas diminutos que se comen enteros, piel incluida.', '<p>El quinoto es el más insólito de todos los cítricos: sus frutos miniatura, de apenas 3-4 cm, se comen enteros — la piel dulce, la pulpa ácida. Una combinación de sabores que sorprende y genera adicción. Y como árbol decorativo es simplemente exquisito: sus frutos pequeños y perfectos colgando entre el follaje verde oscuro crean una imagen de una elegancia difícil de igualar.</p><p>Es también uno de los cítricos más compactos y mejor adaptados para maceta interior o exterior. Puede vivir en una maceta mediana durante años sin perder su frondosidad ni su capacidad de dar frutos. Un árbol que se puede tener en un balcón pequeño y que igualmente impresiona.</p><p>Como regalo es uno de los más originales: pocas personas reciben un árbol frutal, y el quinoto tiene una particularidad tan especial que genera siempre una reacción de genuina sorpresa y placer.</p>', 55),
('palta', 'Árbol de Palta', 'plantas', 'Frutales', 12000, 10, 'active', false, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'El árbol de aguacate para jardín o patio. Un proyecto verde de largo plazo con recompensas únicas.', '<p>El árbol de palta — aguacate — es un proyecto de compromiso. No fructifica a los seis meses: puede tomar varios años, dependiendo de las condiciones. Pero ese largo plazo tiene su propia magia. Ver crecer un árbol de palta, ver aparecer las primeras flores, esperar los primeros frutos, es un vínculo que se desarrolla con el tiempo.</p><p>Sus hojas grandes, de un verde profundo y brillante, tienen un aroma propio cuando se las toca — herbáceo y fresco. Es un árbol con presencia imponente incluso antes de dar frutos. Y cuando llegan las paltas propias, la satisfacción es genuinamente difícil de describir.</p><p>Requiere jardín o maceta muy grande, buenas temperaturas y paciencia. Es la planta para las personas que piensan en años, no en semanas.</p>', 56),
('fuente-doble-pajaro', 'Fuente Doble Pájaro', 'fuentes', 'Decorativas', 69000, 10, 'active', true, 'https://images.unsplash.com/photo-1564462369724-4003221599e2?w=700&q=80&auto=format&fit=crop', 'Dos pájaros, agua en movimiento, serenidad constante. Una de las piezas más especiales de la colección.', '<p>El sonido del agua no es decorativo — es terapéutico. La ciencia lo confirma: el sonido del agua fluyendo activa el sistema nervioso parasimpático, reduce el cortisol y lleva al cerebro a un estado de relajación activa. Es por eso que el sonido de la lluvia, los arroyos y las cascadas ha acompañado la meditación humana desde tiempos inmemoriales.</p><p>La Fuente Doble Pájaro trae ese regalo al interior del hogar. Su diseño con dos pájaros sobre la fuente crea una imagen de naturaleza y quietud — como encontrarse con un rincón de jardín dentro de la casa. El agua circula de manera continua, silenciosa, constante.</p><p>En términos de feng shui, el agua en movimiento activa el chi (energía vital) del espacio, atrae abundancia y mejora el flujo energético de cualquier ambiente. Ubicada en la sala de estar, el estudio o el dormitorio, transforma la calidad del espacio de manera inmediata y permanente.</p><p>Incluye bomba silenciosa de bajo consumo. El depósito requiere recarga semanal según la evaporación. Una inversión en bienestar que se amortiza en los primeros días de uso.</p>', 57),
('fuente-triple-cascada', 'Fuente Triple Cascada', 'fuentes', 'Cascada', 38000, 10, 'active', true, 'https://images.unsplash.com/photo-1564462369724-4003221599e2?w=700&q=80&auto=format&fit=crop', 'Tres niveles de cascada para un sonido envolvente y relajante. Naturaleza en tu living.', '<p>El agua cayendo en cascada tiene algo que el agua estática no tiene: movimiento, ritmo, vitalidad. La Fuente Triple Cascada reproduce ese sonido en tres niveles sucesivos — cada escalón amplifica el efecto relajante del anterior, creando una experiencia sonora que se percibe incluso sin buscarla conscientemente.</p><p>En feng shui, las fuentes con cascadas generan un flujo de energía especialmente activo para la abundancia y la prosperidad. El agua en movimiento descendente hacia una pileta central es uno de los arreglos más favorables que existe para el hogar y la oficina.</p><p>Su diseño es compacto pero con presencia visual. Se puede instalar sobre una mesa, una repisa o el suelo según el tamaño del espacio. Incluye bomba silenciosa y llega lista para enchufar y usar.</p>', 58),
('fuente-ganesha', 'Fuente Ganesha', 'fuentes', 'Ganesha', 33000, 10, 'active', true, 'https://images.unsplash.com/photo-1596045571419-664297d8f502?w=700&q=80&auto=format&fit=crop', 'Ganesha — el removedor de obstáculos — y el fluir constante del agua. Abundancia en movimiento.', '<p>Ganesha es el Señor de los Comienzos en la tradición hindú. El removedor de obstáculos, el abridor de caminos, el dios al que se invoca antes de cualquier empresa importante. Su imagen en el hogar es considerada una invitación permanente a que los caminos se abran, que los bloqueos se disuelvan, que lo nuevo llegue.</p><p>Combinada con el fluir constante del agua — símbolo universal de abundancia, fluidez y vida — esta fuente crea una doble energía de apertura y movimiento. El agua circula alrededor de Ganesha de manera continua, como una ofrenda permanente y un recordatorio de que la vida siempre fluye.</p><p>Como pieza decorativa, su acabado detallado y su tamaño generan una presencia real en el espacio. No es una figurita pequeña — es una pieza que se convierte en el foco de cualquier rincón donde se ubique. Acompañada del sonido suave del agua, transforma cualquier ambiente en un espacio de intención y serenidad.</p>', 59),
('cascada-zen', 'Cascada de Humo Zen', 'cascadas', 'Zen', 18000, 10, 'active', false, 'https://images.unsplash.com/photo-1568990416308-c998af4cf9ee?w=700&q=80&auto=format&fit=crop', 'El humo del incienso cae como cascada. Un efecto visual hipnótico que transforma cualquier espacio.', '<p>Las cascadas de humo son una de las experiencias visuales más hipnóticas que existen en el mundo de la decoración meditativa. El principio es simple y al mismo tiempo completamente mágico: un cono de incienso de flujo inverso, colocado en la cavidad superior, emite humo más denso que el aire. Ese humo cae hacia abajo en lugar de subir — creando una cascada etérea que fluye hacia el suelo como agua en cámara lenta.</p><p>El efecto visual es imposible de describir del todo. Hay que verlo. El humo forma volutas, espirales, corrientes que cambian a cada segundo, nunca exactamente iguales. Es meditativo de una manera completamente distinta al incienso tradicional: el ojo sigue el humo y la mente se calma.</p><p>La cascada Zen tiene un diseño limpio y minimalista. Se adapta a cualquier espacio y cualquier estética — desde la decoración japonesa más austera hasta los interiores contemporáneos. Incluye un set de conos de inicio para comenzar a usarla desde el primer momento.</p>', 60),
('cascada-flor-loto', 'Cascada Flor de Loto', 'cascadas', 'Flor de Loto', 20000, 10, 'active', true, 'https://images.unsplash.com/photo-1568990416308-c998af4cf9ee?w=700&q=80&auto=format&fit=crop', 'El símbolo del renacimiento como cascada de humo. Pureza espiritual hecha objeto.', '<p>La flor de loto es uno de los símbolos espirituales más poderosos del mundo. Crece en el barro, a través del agua turbia, y emerge perfecta e impecable a la superficie. En el budismo, representa la pureza del espíritu que trasciende las circunstancias. En el hinduismo, es el asiento de los dioses. En el yoga, es el símbolo del chakra corona — la conexión máxima.</p><p>Esta cascada de humo en forma de flor de loto convierte ese simbolismo en una experiencia sensorial cotidiana. El humo emerge del centro de la flor y cae por sus pétalos como agua, creando una imagen que tiene algo de sagrado y algo de completamente hipnótico al mismo tiempo.</p><p>Es la cascada más elegida de nuestra colección — y también la más fotografiada. Una pieza que genera conversación, que invita a preguntas, que transforma el ambiente donde descansa.</p>', 61),
('cascada-japonesa', 'Cascada Japonesa', 'cascadas', 'Japonesa', 22000, 10, 'active', false, 'https://images.unsplash.com/photo-1606744837616-56c9a5c6a6eb?w=700&q=80&auto=format&fit=crop', 'Estética wabi-sabi japonesa: simplicidad, intención y humo en perfecta armonía.', '<p>El wabi-sabi es la estética japonesa de la belleza en la imperfección y la impermanencia. Un plato con una grieta. Un jardín donde la hierba crece entre las piedras. Una noche de niebla. Esta cascada de humo captura esa filosofía en cada línea: formas simples, deliberadas, sin ornamento innecesario.</p><p>La tradición japonesa del incienso — el kōdō — es tan refinada como la ceremonia del té. No se trata solo de un aroma: es una práctica de atención plena, de presencia en el momento. Esta cascada transforma el encendido de un cono en un ritual.</p><p>El humo que desciende por sus formas crea un efecto visual que encaja perfectamente con la estética japonesa: dinámico pero sereno, vivo pero quieto. Una contradicción que solo el humo puede resolver.</p>', 62),
('cascada-escalera', 'Cascada Triple Escalera', 'cascadas', 'Escalera', 19000, 10, 'active', false, 'https://images.unsplash.com/photo-1568990416308-c998af4cf9ee?w=700&q=80&auto=format&fit=crop', 'El humo desciende escalonado en tres niveles. Un efecto visual arquitectónico y meditativo.', '<p>La Cascada Triple Escalera tiene algo de arquitectura sagrada: sus tres niveles descendentes evocan los templos mayas, las pirámides escalonadas, los ziggurat de Mesopotamia. La idea de que lo sagrado se alcanza subiendo — y que la purificación viene al descender — está presente en todas las culturas del mundo.</p><p>El humo cae de escalón en escalón con un ritmo hipnótico: primero el primer nivel, luego el segundo, luego el tercero. El movimiento es escalonado, medido, casi musical. Creado específicamente para quienes quieren una cascada de humo con más estructura visual que las versiones orgánicas.</p><p>Funciona perfectamente sobre una mesa, una repisa o un altar. Su silueta es reconocible incluso cuando no está en uso — una pieza decorativa de presencia independiente de si hay o no incienso encendido.</p>', 63),
('cascada-piedra', 'Cascada de Piedra Natural', 'cascadas', 'Piedra', 21000, 10, 'active', false, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=700&q=80&auto=format&fit=crop', 'Base de piedra natural real y humo etéreo. Los elementos tierra y aire en un solo objeto.', '<p>Esta cascada tiene algo que las demás no tienen: es parcialmente natural. Su base no es resina ni cerámica — es piedra real, con toda la textura, el peso y la energía que eso implica. El resultado es una pieza que une los dos extremos del espectro material: lo sólido y permanente de la roca, y lo etéreo e impermanente del humo.</p><p>El contraste es visualmente poderoso: la piedra gris o beige natural, densa y quieta, y el humo blanco que fluye sobre ella como si la piedra misma respirara. En términos de elementos, es la unión de la tierra y el aire — dos energías complementarias que se potencian mutuamente.</p><p>Como objeto decorativo funciona incluso sin incienso: la piedra natural tiene suficiente presencia y belleza para justificarse sola. Y cuando el humo corre sobre ella, la pieza alcanza un nivel de sofisticación visual difícil de igualar.</p>', 64),
('buda-meditativo', 'Buda Meditativo', 'decoracion', 'Budas', 25000, 10, 'active', false, 'https://images.unsplash.com/photo-1596045571419-664297d8f502?w=700&q=80&auto=format&fit=crop', 'Presencia, serenidad y sabiduría. Una figura que transforma la energía del espacio donde descansa.', '<p>El Buda no es solo una figura decorativa — es un recordatorio constante de que la quietud interior es posible en cualquier momento. Siddhartha Gautama, el Buda histórico, encontró la iluminación no en la acción sino en la inmovilidad perfecta: sentado bajo el árbol Bodhi, inmóvil pero completamente presente. Esa energía es la que lleva consigo esta figura.</p><p>En cualquier espacio donde se ubique, el Buda meditativo genera un campo de calma. No es algo que pueda medirse en un laboratorio, pero cualquier persona sensible lo percibe: hay espacios donde entrar y respirar diferente. El Buda ayuda a crear ese espacio.</p><p>Elaborado en resina de alta calidad con acabado detallado, tiene el peso y la presencia de una pieza pensada para durar. No es una figurita frágil — es una pieza de decoración consciente diseñada para acompañar un espacio durante muchos años.</p>', 65),
('buda-paz', 'Buda de la Paz', 'decoracion', 'Budas', 22000, 10, 'active', false, 'https://images.unsplash.com/photo-1596045571419-664297d8f502?w=700&q=80&auto=format&fit=crop', 'El Buda con las manos levantadas en gesto de paz. Protección, armonía y serenidad para el hogar.', '<p>El Buda de la Paz presenta las manos levantadas con las palmas hacia afuera — el mudra (gesto sagrado) del abhaya, que significa "no temas". Es una figura que irradia protección activa: no la que cierra y bloquea, sino la que abre y calma. Un guardián gentil del espacio.</p><p>En la tradición budista, este gesto simboliza la protección, la benevolencia y la disipación del miedo. Colocado en la entrada del hogar o en la sala, transmite a quienes ingresan una sensación inmediata de bienvenida y seguridad.</p><p>Como regalo es perfecto para hogares nuevos, mudanzas, inauguraciones de oficinas o cualquier momento donde alguien esté comenzando algo nuevo y quiera llenarlo de buena energía desde el principio.</p>', 66),
('buda-fortuna', 'Buda de la Fortuna', 'decoracion', 'Budas', 23000, 10, 'active', false, 'https://images.unsplash.com/photo-1596045571419-664297d8f502?w=700&q=80&auto=format&fit=crop', 'El Hotei, el Buda de la buena suerte y la abundancia. Risa, fortuna y prosperidad en el hogar.', '<p>El Buda de la Fortuna — conocido en China como Hotei o Budai — es el más reconocible de todos: regordete, sonriente, con la panza expuesta y los brazos abiertos. No es el Buda histórico sino un monje chino del siglo X que se convirtió en símbolo de la alegría, la abundancia y la buena fortuna.</p><p>Según la tradición, si se frota su panza, trae suerte. Si se ubica mirando hacia la puerta de entrada, atrae la prosperidad que llega desde afuera. Si mira hacia el interior del hogar, la retiene y la distribuye por todo el espacio.</p><p>Su risa amplia es contagiosa — es imposible no sonreír al verlo. Es una pieza que genera alegría simplemente por su presencia, y eso ya es un tipo de abundancia que vale mucho.</p>', 67),
('buda-sonadora', 'Buda Soñadora', 'decoracion', 'Budas', 18000, 10, 'active', false, 'https://images.unsplash.com/photo-1596045571419-664297d8f502?w=700&q=80&auto=format&fit=crop', 'La Buda reclinada con la mejilla apoyada en la mano. Contemplación, sueños y descanso interior.', '<p>La Buda Soñadora tiene una energía diferente a todos los demás Budas de la colección: no está sentada en meditación ni de pie en postura de poder — está reclinada, con la mejilla suavemente apoyada en la mano, con una sonrisa apenas esbozada. Parece estar a punto de dormirse o de despertar de un sueño hermoso.</p><p>Su energía es la del descanso consciente, la contemplación y la sabiduría que no necesita hacer nada para existir. Un recordatorio de que también hay valor en parar, en descansar, en soñar. En una cultura que premia la productividad constante, la Buda Soñadora es casi un acto político.</p><p>Es una de nuestras figuras más elegidas para dormitorios, cuartos de lectura y espacios de descanso. También es uno de los regalos más acertados — porque todos, en algún momento, necesitan que alguien les recuerde que está bien parar.</p>', 68),
('trio-budas-sabios', 'Trío Budas Sabios', 'decoracion', 'Budas', 32000, 10, 'active', true, 'https://images.unsplash.com/photo-1596045571419-664297d8f502?w=700&q=80&auto=format&fit=crop', 'Los tres monos sabios: no ver, no escuchar, no decir. Sabiduría ancestral en tres figuras.', '<p>Los tres monos sabios son uno de los símbolos más reconocidos y más malinterpretados del mundo. Mizaru (que se tapa los ojos), Kikazaru (que se tapa los oídos) y Iwazaru (que se tapa la boca) no representan la ignorancia deliberada — representan tres formas de sabiduría: no mirar lo que daña al alma, no escuchar lo que envenena la mente, no hablar cuando las palabras no suman.</p><p>Originarios del santuario sintoísta de Nikkō, Japón, su imagen se remonta al siglo XVII aunque el concepto es mucho más antiguo, presente en la filosofía confuciana. En el mundo contemporáneo, son un recordatorio de que la sabiduría también implica selectividad — elegir conscientemente qué se recibe y qué se emite.</p><p>Como trío decorativo, tienen una presencia visual poderosa. Pueden disponerse en línea horizontal o en escalera. Son una pieza de conversación garantizada en cualquier espacio.</p>', 69),
('lechuza-decorativa', 'Lechuza Decorativa', 'decoracion', 'Lechuzas', 18000, 10, 'active', false, 'https://images.unsplash.com/photo-1596045571419-664297d8f502?w=700&q=80&auto=format&fit=crop', 'La lechuza: sabiduría, intuición y capacidad de ver lo invisible. Un símbolo atemporal.', '<p>La lechuza ha sido símbolo de sabiduría en casi todas las culturas del mundo. En la antigua Grecia, era el ave de Atenea, diosa de la sabiduría. En la Roma antigua, predecía el futuro. En la cultura celta, era mensajera entre el mundo de los vivos y el de los muertos. En la tradición mesoamericana, guardiana de los secretos de la noche.</p><p>Su poder simbólico se debe a una característica física real: puede girar la cabeza 270 grados y ver en la oscuridad total. Es la criatura que ve lo que otros no pueden ver. Por eso, como símbolo, representa la intuición, el conocimiento profundo y la capacidad de discernir la verdad cuando los demás solo ven confusión.</p><p>Como pieza decorativa, tiene una presencia elegante y atemporal. Funciona en cualquier estilo de interior — desde lo más clásico hasta lo más contemporáneo.</p>', 70),
('trio-lechuzas-sabias', 'Trío Lechuzas Sabias', 'decoracion', 'Lechuzas', 28000, 10, 'active', false, 'https://images.unsplash.com/photo-1596045571419-664297d8f502?w=700&q=80&auto=format&fit=crop', 'Tres lechuzas de distintos tamaños. La familia de la sabiduría para espacios que valoran el conocimiento.', '<p>El trío de lechuzas sabias es una de las composiciones decorativas más elegantes de la colección. Tres figuras de tamaños diferentes — mayor, mediana y pequeña — crean una familia de sabiduría que funciona como punto focal en cualquier estante, mesa o repisa.</p><p>La variación de tamaños genera una composición visual natural y equilibrada — como si las tres existieran juntas por razones propias, no por diseño. Es ese tipo de decoración que parece fácil pero que tiene detrás un criterio cuidadoso.</p><p>Como regalo para personas que aman el conocimiento, la lectura, la filosofía o el arte, es de los más acertados. Dice: "valoro lo que sabés, lo que pensás, lo que ves donde otros no ven."</p>', 71),
('llama-cactus', 'Llama con Cactus', 'decoracion', 'Llamas', 16000, 10, 'active', false, 'https://images.unsplash.com/photo-1650208532541-572697b3dd40?w=700&q=80&auto=format&fit=crop', 'Llama andina con cactus integrado. Artesanía pintada a mano con carácter y energía de altura.', '<p>La llama es el animal más representativo de los Andes sudamericanos. Durante siglos fue el principal medio de transporte en las alturas de la Puna, la guardiana de los rebaños, el símbolo de la resistencia y la adaptación en condiciones extremas. Hoy es también un ícono cultural que combina lo ancestral con lo contemporáneo de una manera completamente natural.</p><p>Esta versión incluye un pequeño cactus integrado en su lomo — el cactus, símbolo de la resistencia en el desierto, de la belleza que crece donde parece imposible. La combinación no es casual: llama y cactus son dos símbolos de adaptación, de vida en lugares difíciles, de belleza que no pide condiciones perfectas para florecer.</p><p>Pintada a mano con colores vibrantes inspirados en los textiles andinos. Cada una tiene diferencias únicas — en el trazo, en la distribución del color, en el detalle. Artesanía genuina.</p>', 72),
('llama-suculenta', 'Llama con Suculenta', 'decoracion', 'Llamas', 18000, 10, 'active', false, 'https://images.unsplash.com/photo-1650208532541-572697b3dd40?w=700&q=80&auto=format&fit=crop', 'Llama andina con suculenta viva. La combinación perfecta de artesanía y naturaleza real.', '<p>La llama con suculenta lleva el concepto de la llama decorativa a otro nivel: en lugar de un cactus de cerámica, lleva una suculenta viva en su lomo. Es una pieza que es simultáneamente artesanía pintada a mano y planta de interior — una escultura viva que cambia y crece con el tiempo.</p><p>Las suculentas son las plantas más fáciles del mundo de cuidar: requieren riego cada dos semanas, toleran el olvido con elegancia y tienen una belleza geométrica y silenciosa que complementa perfectamente la energía colorida de la llama andina.</p><p>Con el tiempo, la suculenta crece y la pieza evoluciona. Es una decoración que tiene vida propia — que no se congela en el momento en que se compra sino que continúa cambiando, como todo lo que es realmente vivo.</p>', 73),
('llama-pequena', 'Llama Pequeña', 'decoracion', 'Llamas', 9000, 10, 'active', false, 'https://images.unsplash.com/photo-1650208532541-572697b3dd40?w=700&q=80&auto=format&fit=crop', 'La llama más pequeña de la colección. Para escritorios, estantes y corazones que aman los Andes.', '<p>Pequeña en tamaño, grande en carácter. La llama pequeña es la versión compacta de nuestro ícono andino — perfecta para escritorios, mesas de luz, estantes con poco espacio o cualquier rincón que pida un poco de color y personalidad sin que ocupe demasiado lugar.</p><p>Pintada a mano con los mismos colores vibrantes y el mismo detalle que sus versiones más grandes. Cada una es diferente — las variaciones del trazo, los colores específicos y los pequeños detalles hacen que no existan dos llamas pequeñas exactamente iguales.</p><p>Es también uno de nuestros regalos más accesibles y más acertados: una llama andina nunca falla porque siempre genera una sonrisa. Para cumpleaños, souvenirs significativos o simplemente como detalle de afecto.</p>', 74),
('porta-sahumerio-mano-fatima', 'Porta Sahumerio Mano de Fátima', 'decoracion', 'Porta Sahumarios', 8500, 10, 'active', false, 'https://images.unsplash.com/photo-1606744837616-56c9a5c6a6eb?w=700&q=80&auto=format&fit=crop', 'La Hamsa (Mano de Fátima) como porta sahumerios. Protección, prosperidad y bendición del hogar.', '<p>La Hamsa — también conocida como Mano de Fátima en el mundo árabe y Mano de Miriam en la tradición judía — es uno de los símbolos de protección más extendidos del mundo. Presente en el norte de África, el Medio Oriente y la Europa mediterránea desde hace miles de años, protege contra el mal de ojo y atrae la buena fortuna.</p><p>Su forma de mano abierta con el ojo en el centro es inmediatamente reconocible. En este porta sahumerios, esa forma sostiene el palo de incienso y recoge la ceniza, convirtiéndose en un objeto funcional y sagrado al mismo tiempo. Mientras el incienso arde, la Hamsa trabaja: protege el espacio, bendice el ambiente, atrae lo positivo.</p><p>Como objeto decorativo funciona incluso sin incienso — la Hamsa sola ya es una pieza con presencia y significado. Un detalle elegante y lleno de historia para cualquier rincón del hogar.</p>', 75),
('porta-sahumerio-buda', 'Porta Sahumerio Buda', 'decoracion', 'Porta Sahumarios', 8500, 10, 'active', false, 'https://images.unsplash.com/photo-1596045571419-664297d8f502?w=700&q=80&auto=format&fit=crop', 'El Buda como soporte del incienso. Meditación, aroma y presencia espiritual en un solo objeto.', '<p>En la tradición budista, el incienso no es decorativo ni aromático en primer lugar — es una ofrenda. El humo que sube lleva los pensamientos y las intenciones hacia lo más elevado. Este porta sahumerios une esa práctica con la figura del Buda, creando un objeto que es simultáneamente funcional, decorativo y profundamente espiritual.</p><p>El Buda sostiene el palo de incienso mientras el humo asciende a su alrededor. La imagen tiene una quietud particular: la figura meditativa, el movimiento del humo, el aroma llenando el espacio. Es un ritual diario que puede ser tan simple como encender un palo de incienso o tan profundo como una práctica de meditación.</p><p>Como objeto decorativo permanece hermoso incluso entre uso y uso. La figura del Buda sobre su base de cerámica o resina es una presencia en sí misma.</p>', 76),
('porta-sahumerio-loto', 'Porta Sahumerio Flor de Loto', 'decoracion', 'Porta Sahumarios', 9000, 10, 'active', false, 'https://images.unsplash.com/photo-1606744837616-56c9a5c6a6eb?w=700&q=80&auto=format&fit=crop', 'La flor de loto sostiene el incienso. Pureza, renacimiento y aroma en un solo gesto sagrado.', '<p>La flor de loto es el símbolo de la pureza espiritual por excelencia — la flor que crece en el barro y emerge perfecta, impoluta, hacia la luz. En este porta sahumerios, esa flor sostiene el incienso: el objeto más puro sosteniendo la ofrenda más etérea.</p><p>La imagen de un palo de incienso ardiendo sobre una flor de loto tiene una belleza casi poética. El humo asciende desde los pétalos como si la flor misma respirara y emanara su esencia. Es un objeto que convierte el acto cotidiano de encender incienso en una imagen de meditación y belleza.</p><p>La base de loto recoge la ceniza del incienso mientras mantiene su forma abierta y receptiva. Funcional, hermosa y llena de significado — exactamente como debería ser todo lo que elegimos para nuestros espacios.</p>', 77),
('lampara-buda-sonadora', 'Lámpara Buda Soñadora', 'lamparas', 'Buda', 42000, 10, 'active', true, 'https://images.unsplash.com/photo-1623241923490-5b2fd532828f?w=700&q=80&auto=format&fit=crop', 'La más especial de la colección. El Buda soñador en sal del Himalaya que purifica, entibia y armoniza.', '<p>La sal del Himalaya tiene 250 millones de años. Se formó en los mares primordiales que existían antes de que las montañas existieran, y quedó atrapada cuando la tierra se elevó. Es un mineral con una historia geológica que pone en perspectiva cualquier preocupación cotidiana.</p><p>Cuando se calienta con la bombilla, la sal emite iones negativos — el mismo fenómeno que ocurre en la orilla del mar, en las cascadas y después de la lluvia. Los iones negativos se asocian científicamente con la mejora del estado de ánimo, la reducción del estrés y la mejora de la calidad del aire. También, su luz ámbar cálida reduce la producción de cortisol y facilita la relajación profunda.</p><p>La figura del Buda Soñadora — reclinada, serena, con esa sonrisa apenas esbozada — convierte esta lámpara en algo más que una fuente de luz. Es una presencia. Una compañía silenciosa que transforma el espacio donde descansa en un refugio de calma y calidez.</p><p>Puede estar encendida las 24 horas — de hecho, funciona mejor así: la sal necesita calor sostenido para liberar sus beneficios de manera constante. Es una inversión en bienestar que se percibe desde la primera noche.</p>', 78),
('lampara-buda-guerrero', 'Lámpara Buda Guerrero', 'lamparas', 'Buda', 42000, 10, 'active', false, 'https://images.unsplash.com/photo-1623241923490-5b2fd532828f?w=700&q=80&auto=format&fit=crop', 'El guerrero espiritual en sal del Himalaya. Fuerza, protección y luz cálida para el hogar.', '<p>El Buda guerrero no es el Buda de la quietud pasiva — es el Buda de la determinación activa. Representa la fuerza espiritual necesaria para enfrentar los obstáculos internos: los miedos, las dudas, los hábitos que frenan el crecimiento. Es la energía del que avanza con consciencia y sin violencia.</p><p>En sal del Himalaya, esa energía de fuerza y determinación se combina con los beneficios de ionización y purificación del mineral. El resultado es una lámpara que no solo ilumina y calienta — sino que sostiene la energía del espacio con una vibración de claridad y poder interior.</p><p>Ideal para estudios, oficinas en el hogar, espacios de entrenamiento o cualquier ambiente donde se trabaje hacia objetivos concretos. Una presencia que recuerda que la fuerza más importante no viene de afuera.</p>', 79),
('lampara-elefante', 'Lámpara Elefante', 'lamparas', 'Elefante', 40000, 10, 'active', false, 'https://images.unsplash.com/photo-1623241923490-5b2fd532828f?w=700&q=80&auto=format&fit=crop', 'El elefante con la trompa levantada — símbolo universal de buena suerte — en sal del Himalaya.', '<p>En casi todas las culturas asiáticas, el elefante con la trompa levantada es el símbolo más poderoso de prosperidad, buena suerte y sabiduría. En India, el elefante es la manifestación de Ganesha. En Tailandia, es el animal sagrado del rey. En el feng shui chino, atrae la riqueza y el buen chi cuando se coloca en la entrada del hogar.</p><p>Esta lámpara combina ese simbolismo milenario con los beneficios reales de la sal del Himalaya: ionización negativa del aire, luz cálida que reduce el cortisol y una presencia térmica suave que calienta el ambiente en los meses fríos.</p><p>La figura del elefante tallada en la sal rosa crea una silueta cálida y reconocible. Encendida, la luz ámbar que emana por las vetas naturales de la sal es completamente única — nunca exactamente igual en dos piezas.</p>', 80),
('lampara-angelito', 'Lámpara Angelito', 'lamparas', 'Ángel', 38000, 10, 'active', false, 'https://images.unsplash.com/photo-1623241923490-5b2fd532828f?w=700&q=80&auto=format&fit=crop', 'Un ángel en sal del Himalaya. Protección, paz y luz suave para dormitorios y espacios de descanso.', '<p>El ángel es el símbolo de la protección y la guía en casi todas las tradiciones espirituales del mundo. Esta lámpara de sal con figura de ángel lleva esa energía de protección al espacio cotidiano de la manera más hermosa posible: con luz.</p><p>La luz ámbar suave que emite la sal del Himalaya es la más cercana a la luz de vela que existe en iluminación eléctrica. No excita la retina, no interfiere con la producción de melatonina, no estimula el sistema nervioso. Es la luz ideal para las horas previas al sueño — cuando el cuerpo necesita señales de calma, no de activación.</p><p>Es uno de los regalos más elegidos de toda la colección — para dormitorios, para cuartos de bebé, para personas mayores, para cualquier espacio donde la paz y la protección sean más que decorativas. Una lámpara que puede estar encendida toda la noche sin problema, cumpliendo su función de guardia silenciosa del descanso.</p>', 81),
('sahumerio-lavanda', 'Sahumerio Lavanda', 'aromaterapia', 'Sahumerios', 1200, 10, 'active', false, 'https://images.unsplash.com/photo-1639390167093-9c62311fe84d?w=700&q=80&auto=format&fit=crop', 'El aroma más relajante del mundo. Lavanda para calmar el sistema nervioso y preparar el sueño.', '<p>La lavanda es la planta más estudiada científicamente en términos de efectos sobre el sistema nervioso. Decenas de estudios confirman lo que las tradiciones mediterráneas sabían desde hace siglos: su aroma reduce el cortisol, disminuye la frecuencia cardíaca y lleva al sistema nervioso a un estado de calma activa. No es folklore — es fisiología.</p><p>El sahumerio de lavanda lleva ese aroma al espacio de una manera lenta y sostenida. A diferencia del difusor eléctrico, el sahumerio crea una experiencia ritual: encenderlo, ver el humo, percibir cómo el aroma llena el ambiente gradualmente. Ese proceso en sí mismo es un momento de pausa.</p><p>Ideal para la hora antes de dormir, para los momentos de meditación o yoga, para cualquier instante donde la mente necesite bajar de velocidad. El aroma de lavanda en un espacio crea un condicionamiento ambiental: el cerebro empieza a asociarlo con la calma y el descanso.</p>', 82),
('sahumerio-romero', 'Sahumerio Romero', 'aromaterapia', 'Sahumerios', 1200, 10, 'active', false, 'https://images.unsplash.com/photo-1639390167093-9c62311fe84d?w=700&q=80&auto=format&fit=crop', 'Activador mental y purificante de espacios. El romero despierta la mente y limpia la energía.', '<p>El romero tiene una energía completamente diferente a la lavanda: no relaja sino que activa. Su aroma vigoroso, fresco y ligeramente mentolado es estimulante para el sistema nervioso y se ha demostrado que mejora la memoria y la concentración a corto plazo. Es el incienso del trabajo intelectual.</p><p>En la tradición medieval europea, el romero era la hierba de la memoria — se colocaba en los libros de estudio, se llevaba en la ropa durante los exámenes, se quemaba en los estudios de los alquimistas y los filósofos. Esa reputación tiene fundamento botánico real: el 1,8-cineol del romero mejora la función cognitiva de manera medible.</p><p>Como purificante energético de espacios, el romero limpia lo estancado y activa el flujo de energía. Ideal para usar al comenzar la semana laboral, al abrir un espacio que estuvo cerrado, al iniciar un proyecto nuevo.</p>', 83),
('sahumerio-madre-tierra', 'Sahumerio Madre Tierra', 'aromaterapia', 'Sahumerios', 1500, 10, 'active', false, 'https://images.unsplash.com/photo-1639390167093-9c62311fe84d?w=700&q=80&auto=format&fit=crop', 'Tierra, hierbas y raíces. Para conectar con lo ancestral, el arraigo y los ciclos de la naturaleza.', '<p>El Sahumerio Madre Tierra tiene un aroma que lleva directo a la tierra: profundo, húmedo, herbáceo, con notas de raíces y plantas silvestres. Es el aroma más telúrico de la colección — el que más conecta con el elemento tierra, con el arraigo, con la sensación de pertenecer a algo más grande y más antiguo que uno mismo.</p><p>En muchas tradiciones ancestrales latinoamericanas, quemar hierbas de la tierra forma parte de los rituales de arraigo, de gratitud a la Pachamama y de limpieza de espacios. El humo no solo purifica el ambiente — crea un puente entre el espacio cotidiano y la dimensión sagrada de la naturaleza.</p><p>Ideal para rituales de inicio de ciclos, para espacios de meditación profunda, para momentos donde se necesita bajar y conectar con el cuerpo y la tierra después de mucho tiempo "en la cabeza".</p>', 84),
('sahumerio-sagrada-madre', 'Sahumerio Sagrada Madre', 'aromaterapia', 'Sahumerios', 1500, 10, 'active', false, 'https://images.unsplash.com/photo-1639390167093-9c62311fe84d?w=700&q=80&auto=format&fit=crop', 'Mezcla de hierbas sagradas para limpieza espiritual profunda y conexión con lo elevado.', '<p>La Sagrada Madre es nuestra mezcla más especial: una combinación de hierbas con historia de uso ritual en distintas tradiciones espirituales de América Latina. No existe una fórmula única para este tipo de mezclas — cada casa, cada curandera, cada tradición tiene la suya. La nuestra está pensada para la limpieza espiritual profunda y la apertura a lo nuevo.</p><p>Su aroma es complejo: hay notas dulces y notas amargas, lo floral y lo resinoso, lo suave y lo poderoso. Es un aroma que no se parece a nada más, que cuando lo percibís por primera vez genera una sensación difícil de describir: como si el espacio se abriera, como si el aire se volviera más ligero.</p><p>Se usa en momentos de transición importante: mudanzas, divorcios, finales de relaciones, comienzos de proyectos, duelos, celebraciones. Cualquier momento donde un ciclo termina y otro comienza.</p>', 85),
('palo-santo', 'Palo Santo', 'aromaterapia', 'Palo Santo', 3500, 10, 'active', true, 'https://images.unsplash.com/photo-1639390167093-9c62311fe84d?w=700&q=80&auto=format&fit=crop', 'El árbol sagrado de Sudamérica. Limpieza, protección y elevación espiritual con un aroma único e inconfundible.', '<p>El Bursera graveolens — palo santo — es un árbol que crece en la costa del Pacífico de América del Sur. Su nombre en español lo dice todo: madera sagrada. Fue usado por los incas en rituales de purificación y por los chamanes andinos en ceremonias de curación. Hoy, su popularidad se ha extendido por todo el mundo — y con razón.</p><p>Lo que hace único al palo santo no es solo su aroma — aunque ese aroma es completamente particular, una mezcla de madera, cítrico y menta que no se parece a nada más. Lo que lo hace único es que solo los árboles que murieron de manera natural y reposaron en el suelo durante años desarrollan su resina aromática. No se puede fabricar artificialmente ni acelerar el proceso. Cada palo que llega a nuestras manos tiene décadas de historia.</p><p>Su humo limpia el espacio de energías densas, protege el campo energético y eleva la vibración. Es el ritual de limpieza más accesible y más poderoso que existe: un fósforo, una intención, un momento.</p>', 86),
('aceites-esenciales', 'Aceites Esenciales', 'aromaterapia', 'Aceites', 8500, 10, 'active', false, 'https://images.unsplash.com/photo-1639390167093-9c62311fe84d?w=700&q=80&auto=format&fit=crop', 'Aceites esenciales 100% puros para difusor, masajes y aromaterapia terapéutica.', '<p>La aromaterapia no es nueva age — es química. Los aceites esenciales son concentrados de los compuestos volátiles de plantas: lavanda, eucalipto, árbol del té, naranja, menta, pino, ylang ylang. Cada uno tiene una composición química específica con efectos medibles sobre el sistema nervioso, el estado de ánimo y la respuesta inmune.</p><p>Nuestros aceites esenciales son 100% puros y naturales, sin diluciones, sin sintéticos, sin rellenos. Eso hace que la cantidad necesaria para el efecto sea menor — unas pocas gotas en el difusor son suficientes para transformar el ambiente de una habitación.</p><p>Se pueden usar en difusor eléctrico (la forma más efectiva para aromatizar el espacio), en la bañera (5-6 gotas con sales de baño), en el hornito de esencias con vela, en masajes corporales diluidos en aceite base, o en la almohada para el sueño. Una herramienta de bienestar completamente versátil.</p>', 87),
('hornito-esencias', 'Hornito de Esencias', 'aromaterapia', 'Hornito', 12000, 10, 'active', false, 'https://images.unsplash.com/photo-1609850280339-b85f1fd5d351?w=700&q=80&auto=format&fit=crop', 'El ritual de la vela y el aroma. Hornito artesanal para aceites esenciales con luz de vela cálida.', '<p>El hornito de esencias es la forma más antigua y más poética de la aromaterapia: una pequeña vela calienta suavemente el agua con aceite esencial en la cazoleta superior, liberando el aroma de manera gradual y envolvente. No es rápido como el difusor eléctrico — es lento, intencional, ritual.</p><p>Encender una vela, agregar unas gotas de aceite esencial, esperar a que el aroma llene el espacio: son gestos simples que se convierten en un momento de pausa. En una vida que corre, el hornito de esencias invita a detenerse, a estar presente, a percibir.</p><p>La luz de vela que emana por debajo mientras el aroma se difunde crea un ambiente de calidez y recogimiento incomparable. Es también una pieza decorativa hermosa cuando no está en uso — su forma artesanal tiene una presencia elegante en cualquier espacio.</p><p>Compatible con todos nuestros aceites esenciales y con cualquier aceite natural. Incluye instrucciones de uso y recomendaciones de aromas por intención.</p>', 88),
('terrario-mediano', 'Terrario Mediano', 'terrarios', 'Mediano', 22000, 10, 'active', false, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'Un ecosistema completo en miniatura. El jardín que se cuida prácticamente solo.', '<p>Un terrario cerrado es una maravilla de la biología aplicada a la decoración. Las plantas transpiran agua, esa agua se condensa en las paredes del vidrio, baja de nuevo al sustrato y las plantas la absorben. Un ciclo cerrado, completo, autónomo. El primer terrario cerrado que se conoce en la historia estuvo sellado durante 53 años sin ningún riego adicional.</p><p>Nuestros terrarios medianos están armados a mano con una selección de plantas de interior que prosperan en ambientes húmedos y cerrados: musgos, helechos miniatura, selaginelas. El sustrato es multicapa — carbón activo para evitar malos olores, turba especial para retener humedad, tierra liviana para las raíces. Todo pensado para que el sistema funcione de manera autónoma.</p><p>Como regalo es, por muchos motivos, el más especial de la colección. No se puede comprar en cualquier lugar. No se puede fabricar sin conocimiento. Y produce una reacción de asombro genuino cada vez que alguien lo ve: ¿cómo puede existir algo tan pequeño, tan perfecto y tan vivo?</p>', 89),
('terrario-grande', 'Terrario Grande', 'terrarios', 'Grande', 35000, 10, 'active', false, 'https://images.unsplash.com/photo-1764422097784-0eaa2340d0e1?w=700&q=80&auto=format&fit=crop', 'Una obra de arte viva de gran formato. El regalo más extraordinario para cualquier ocasión.', '<p>El terrario grande es nuestra pieza más impactante y más ambiciosa. En un recipiente de vidrio de gran formato, con múltiples plantas, piedras decorativas, musgo vivo, pequeñas figuras y sustrato multicapa cuidadosamente dispuesto, cada terrario grande es una composición artística que también es un ecosistema funcional.</p><p>El proceso de armado toma horas. Cada elemento se coloca con intención: las plantas en las posiciones donde van a prosperar, las piedras creando contraste de texturas, el musgo cubriendo los espacios para dar unidad al conjunto. El resultado es diferente en cada pieza — no existe ningún terrario grande igual a otro.</p><p>Como elemento decorativo, tiene la capacidad de ser el foco visual de cualquier espacio: una mesa de centro, una repisa amplia, un escritorio grande. Una ventana de naturaleza viva dentro de cualquier ambiente. Como regalo, no tiene equivalente: es original, es único, es vivo, es bello, es duradero. Todo lo que un buen regalo debería ser.</p>', 90)
insert into faqs (id, question, answer, category, active, sort_order) values
('f1', '¿Las piedras son naturales y auténticas?',        'Sí. Trabajamos únicamente con cristales naturales, sin teñidos ni imitaciones. Cada piedra es única.',                                                  'Piedras',  true, 1),
('f2', '¿Hacen envíos a todo el país?',                   'Realizamos envíos a toda la Argentina. Coordinamos método y costo por WhatsApp según tu ubicación.',                                                    'Envíos',   true, 2),
('f3', '¿Cómo elijo qué piedra o planta me conviene?',    'Podés guiarte por la intención que buscás o escribirnos: te armamos una recomendación personalizada sin cargo.',                                        'Compras',  true, 3),
('f4', '¿Las plantas vienen con instrucciones de cuidado?','Cada planta se entrega con una ficha de cuidado simple: luz, riego y consejos para que se adapte a tu casa.',                                          'Plantas',  true, 4),
('f5', '¿Puedo comprar para regalar?',                    'Por supuesto. Ofrecemos packaging especial para regalo y podemos incluir una tarjeta con tu mensaje.',                                                   'Compras',  true, 5),
('f6', '¿Cómo se realiza el pago?',                       'Coordinamos el pago por WhatsApp: aceptamos transferencia y los principales medios digitales.',                                                         'Compras',  true, 6)
insert into testimonials (id, name, text, rating, product, active, sort_order) values
('t1', 'Camila R.', 'Transformaron por completo mi living. La amatista que me recomendaron es hermosa y la energía del espacio cambió.', 5, 'Amatista Natural',            true, 1),
('t2', 'Martín G.', 'La lámpara de sal es justo lo que buscaba para el dormitorio. Atención impecable y envío cuidado.',                  5, 'Lámpara de Sal del Himalaya', true, 2),
('t3', 'Lucía P.',  'Me asesoraron para armar un rincón de meditación. Cada detalle pensado con muchísimo gusto.',                        5, '',                            true, 3)
insert into blog_posts (id, slug, title, category, read_time, status, sort_order, image) values
('b_feng-shui',         'feng-shui',         'Feng Shui: el arte de dejar fluir la energía del hogar', 'Decoración',    10, 'published', 1, 'https://images.unsplash.com/photo-1606744837616-56c9a5c6a6eb?w=1100&q=80&auto=format&fit=crop'),
('b_lampara-sal',       'lampara-sal',       '¿Para qué sirve una lámpara de sal?',                    'Productos',      5, 'published', 2, 'https://images.unsplash.com/photo-1623241923490-5b2fd532828f?w=1100&q=80&auto=format&fit=crop'),
('b_piedras-significado','piedras-significado','El significado de las piedras energéticas',              'Guía',           8, 'published', 3, 'https://images.unsplash.com/photo-1609216970378-ce61cd74a187?w=1100&q=80&auto=format&fit=crop'),
('b_buda-hogar',        'buda-hogar',        'Qué representa tener un Buda en el hogar',               'Espiritualidad', 6, 'published', 4, 'https://images.unsplash.com/photo-1596045571419-664297d8f502?w=1100&q=80&auto=format&fit=crop'),
('b_limpiar-cristales', 'limpiar-cristales', 'Cómo limpiar energéticamente tus cristales',             'Ritual',         5, 'published', 5, 'https://images.unsplash.com/photo-1597336465111-a392afd218bc?w=1100&q=80&auto=format&fit=crop'),
('b_rincon-meditacion', 'rincon-meditacion', 'Cómo crear un rincón de meditación en casa',             'Espacios',       9, 'published', 6, 'https://images.unsplash.com/photo-1619166855707-bba87a7772a2?w=1100&q=80&auto=format&fit=crop')
